[{"document_id": "1324579", "title": "Regulamento", "url": "https://fnet.bmfbovespa.com.br/fnet/publico/visualizarDocumento?id=1324579", "reference_date": "2026-09-16", "version": "1", "page": 26, "clause": "4.10", "excerpt": "4.10 Nos termos do Art. 45, §7º, inciso II, do Anexo Normativo II da Resolução CVM 175, a Classe  poderá ter até 20% (vinte por cento) de seu Patrimônio Líquido alocado em Direitos Creditórios,  derivativos, observado o disposto no item e Ativos Financeiros devidos por um mesmo Devedor e/ou  de responsabilidade ou coobrigação de Devedores de um mesmo Grupo Econômico e/ou de um mesmo  Devedor, individualmente considerado, ainda que devidos e/ou de responsabilidade ou coobrigação  dos Prestadores de Serviço Essenciais, outros prestadores de serviço da Classe, e/ou suas Partes  Relacionadas.", "sha256": "bf02254f41530cc53501e8dcaa78f5accf688ec1de50899c80b6048061777e30", "verification": "primary_passage"}, {"document_id": "1324579", "title": "Regulamento", "url": "https://fnet.bmfbovespa.com.br/fnet/publico/visualizarDocumento?id=1324579", "reference_date": "2026-09-16", "version": "1", "page": 27, "clause": "4.13.1", "excerpt": "4.13.1 O Gestor monitorará e enviará mensalmente até o 7° Dia Útil de cada mês o Relatório de Gestão  em cada Data de Verificação, conforme informações por ele próprio apuradas e fornecidas pelo  Administrador e Custodiante, dentre as outras obrigações dispostas neste Anexo:
(i) os Índices de Inadimplemento dispostos no item acima;
(ii) os Índices de Monitoramento, exceto o Índice de Subordinação Sênior;
(iii) a Quantidade Mínima de Devedores;
(iv) o Índice de Repasse do Cedente, que não deverá ser superior a 6% (seis por cento);
(v) o Índice de Resolução, o qual não deverá ser superior a 4% (quatro por cento);
(vi) o Limite de Concentração dos 5 Maiores Grupos Econômicos e/ou Indivíduos, o Limite de  Concentração por Grupo Econômico e/ou Indivíduo e o Limite de Concentração por Grupo  Econômico Especial;
(vii) o Prazo Médio dos Direitos Creditórios Cedidos;
(viii) o Índice de Subordinação Sênior,", "sha256": "bf02254f41530cc53501e8dcaa78f5accf688ec1de50899c80b6048061777e30", "verification": "primary_passage"}, {"document_id": "1324579", "title": "Regulamento", "url": "https://fnet.bmfbovespa.com.br/fnet/publico/visualizarDocumento?id=1324579", "reference_date": "2026-09-16", "version": "1", "page": 11, "clause": "", "excerpt": "Limite de Concentração dos 5 é o limite máximo de 25% (vinte e cinco por cento) de  Maiores Grupos Econômicos e/ou concentração no somatório dos 5 (cinco) maiores Grupos  Indivíduos Econômicos, incluindo os Grupos Econômicos Especiais,  considerados em conjunto, devedores de Direitos  Creditórios integrantes da Carteira da Classe em relação ao  Patrimônio Líquido da Classe, que deve ser observado pelo  Custodiante, subcontratado pela Gestora, calculado de  maneira pro forma, em cada Data de Aquisição e  Pagamento, com base em relatórios analíticos  disponibilizados pelo Administrador;", "sha256": "bf02254f41530cc53501e8dcaa78f5accf688ec1de50899c80b6048061777e30", "verification": "primary_passage"}]

[{"document_id": "1324579", "title": "Regulamento", "url": "https://fnet.bmfbovespa.com.br/fnet/publico/visualizarDocumento?id=1324579", "reference_date": "2026-09-16", "version": "1", "page": 27, "clause": "4.13.1", "excerpt": "4.13.1 O Gestor monitorará e enviará mensalmente até o 7° Dia Útil de cada mês o Relatório de Gestão  em cada Data de Verificação, conforme informações por ele próprio apuradas e fornecidas pelo  Administrador e Custodiante, dentre as outras obrigações dispostas neste Anexo:
(i) os Índices de Inadimplemento dispostos no item acima;
(ii) os Índices de Monitoramento, exceto o Índice de Subordinação Sênior;
(iii) a Quantidade Mínima de Devedores;
(iv) o Índice de Repasse do Cedente, que não deverá ser superior a 6% (seis por cento);
(v) o Índice de Resolução, o qual não deverá ser superior a 4% (quatro por cento);
(vi) o Limite de Concentração dos 5 Maiores Grupos Econômicos e/ou Indivíduos, o Limite de  Concentração por Grupo Econômico e/ou Indivíduo e o Limite de Concentração por Grupo  Econômico Especial;
(vii) o Prazo Médio dos Direitos Creditórios Cedidos;
(viii) o Índice de Subordinação Sênior,", "sha256": "bf02254f41530cc53501e8dcaa78f5accf688ec1de50899c80b6048061777e30", "verification": "primary_passage"}, {"document_id": "1324579", "title": "Regulamento", "url": "https://fnet.bmfbovespa.com.br/fnet/publico/visualizarDocumento?id=1324579", "reference_date": "2026-09-16", "version": "1", "page": 34, "clause": "5.20", "excerpt": "5.20 Após a Data da 1ª Integralização de Cotas Seniores, a Índice de Subordinação Sênior deverá ser  igual ou superior a 30% (trinta por cento).", "sha256": "bf02254f41530cc53501e8dcaa78f5accf688ec1de50899c80b6048061777e30", "verification": "primary_passage"}, {"document_id": "1324579", "title": "Regulamento", "url": "https://fnet.bmfbovespa.com.br/fnet/publico/visualizarDocumento?id=1324579", "reference_date": "2026-09-16", "version": "1", "page": 10, "clause": "", "excerpt": "Índice de Subordinação Sênior significa o total de Cotas Subordinadas em relação ao  Patrimônio Líquido da Classe, que deverá ser de, no mínimo,  30% (trinta por cento) durante todo o prazo de duração das  Cotas Seniores;", "sha256": "bf02254f41530cc53501e8dcaa78f5accf688ec1de50899c80b6048061777e30", "verification": "primary_passage"}]

[{"document_id": "769277", "title": "Regulamento", "url": "https://fnet.bmfbovespa.com.br/fnet/publico/visualizarDocumento?id=769277", "reference_date": "2024-10-31", "version": "1", "page": 27, "clause": "7.1", "excerpt": "7.1. A originação e a cessão dos Direitos Creditórios da Classe observarão, no mínimo, os  procedimentos descritos a seguir:
(i) a originação dos Direitos Creditórios Elegíveis se dá por meio (i) da celebração da  Proposta Comercial; e (ii) da realização das Transações de Pagamento pelos Usuários  com a utilização de Instrumentos de Pagamentos para a aquisição de bens ou serviços  junto aos Cedentes;
(ii) os Cedentes encaminharão à Gestora as informações a respeito dos Direitos Creditórios  que pretendem ceder;
(iii) a Gestora verificará o atendimento dos Direitos Creditórios às Condições de Cessão e  realizará a verificação da integridade e titularidade do lastro, na forma da Cláusula 7.4  abaixo, bem como o enquadramento à Política de Investimento, a verificação dos limites  de concentração e o atendimento dos Critérios de Elegibilidade, conforme regras  dispostas no Anexo da Classe Única; e
(iv) cumpridas e aprovadas as etapas anteriores, será realizada a assinatura dos respectivos  Instrumentos de Aquisição, conforme aplicável, e o pagamento do preço de aquisição  pelo Custodiante, em nome do Fundo.", "sha256": "4cb541cb8eabdb38a65a53759ba645963500d51a8c38074beafedb4e470baaa9", "verification": "primary_passage"}, {"document_id": "769277", "title": "Regulamento", "url": "https://fnet.bmfbovespa.com.br/fnet/publico/visualizarDocumento?id=769277", "reference_date": "2024-10-31", "version": "1", "page": 52, "clause": "7.3", "excerpt": "7.3. Por ser destinada exclusivamente a Investidores Profissionais, a Classe não estará sujeita  limites de concentração de sua carteira por devedor, emissor ou tipo de Direito Creditório, nos  termos do artigo 76 do Anexo I da RCVM 175, sem prejuízo do disposto na Cláusula 7.2 acima.", "sha256": "4cb541cb8eabdb38a65a53759ba645963500d51a8c38074beafedb4e470baaa9", "verification": "primary_passage"}]

[{"document_id": "769277", "title": "Regulamento", "url": "https://fnet.bmfbovespa.com.br/fnet/publico/visualizarDocumento?id=769277", "reference_date": "2024-10-31", "version": "1", "page": 2, "clause": "", "excerpt": "Alocação Mínima Significa o enquadramento do percentual mínimo de 67%  (sessenta e sete por cento) do Patrimônio Líquido que  deverá ser alocado em Direitos Creditórios conforme  previsto na Cláusula 7.2 do Anexo da Classe Única.", "sha256": "4cb541cb8eabdb38a65a53759ba645963500d51a8c38074beafedb4e470baaa9", "verification": "primary_passage"}, {"document_id": "769277", "title": "Regulamento", "url": "https://fnet.bmfbovespa.com.br/fnet/publico/visualizarDocumento?id=769277", "reference_date": "2024-10-31", "version": "1", "page": 51, "clause": "7.2", "excerpt": "7.2. Em até 180 (cento e oitenta) dias do início de suas atividades, a Classe deve possuir  parcela superior a 67% (sessenta e sete por cento) de seu Patrimônio Líquido representada por  Direitos Creditórios Alocação Mínima .", "sha256": "4cb541cb8eabdb38a65a53759ba645963500d51a8c38074beafedb4e470baaa9", "verification": "primary_passage"}, {"document_id": "769277", "title": "Regulamento", "url": "https://fnet.bmfbovespa.com.br/fnet/publico/visualizarDocumento?id=769277", "reference_date": "2024-10-31", "version": "1", "page": 59, "clause": "13.2", "excerpt": "13.2. A ocorrência de qualquer das seguintes hipóteses constituirá Evento de Avaliação:
(i) Em caso de insolvência da Administradora ou Gestora;
(ii) Em caso de verificação, a qualquer tempo, de descumprimento superveniente de  quaisquer dos limites de concentração estabelecidos nos incisos (viii) e (ix) da  Cláusula 8.1 acima;
(iii) Em caso de verificação, a qualquer tempo, de que 10% (dez por cento) ou mais do  montante total dos Direitos Creditórios não atendiam aos Critérios de Elegibilidade e às  Condições de Cessão na respectivas Datas de Aquisição;
(iv) Em caso de inobservância, pela Administradora e/ou pela Gestora de suas obrigações  previstas neste Anexo e no Regulamento, desde que, se notificado por escrito pela  Administradora e/ou pela Gestora, conforme o caso, para sanar ou justificar o  descumprimento, não o faça no período máximo de 2 (dois) Dias Úteis contado do  recebimento da referida notificação;
(v) rebaixamento da classificação de risco das Cotas Seniores em circulação (a) a qualquer  tempo, em 3 (três) níveis abaixo da classificação de risco originalmente atribuída, ou (2)  após uma única revisão de classificação de risco ou após 2 (duas) revisões consecutivas,  em 2 (dois) níveis abaixo da classificação de risco originalmente atribuída, conforme  aplicável;
(vi) desenquadramento da Alocação Mínima por mais de 30 (trinta) Dias Úteis consecutivos  sem que haja a correspondente regularização neste período;
(vii) verificação de Patrimônio Líquido Negativo;
(viii) Utilização dos recursos do Fundo em desconformidade com a respectiva Ordem de  Alocação de Recursos;
(ix) desenquadramento de Índice de Subordinação por um período superior ao previsto na  Cláusula 5.1 acima;", "sha256": "4cb541cb8eabdb38a65a53759ba645963500d51a8c38074beafedb4e470baaa9", "verification": "primary_passage"}]

[{"document_id": "769277", "title": "Regulamento", "url": "https://fnet.bmfbovespa.com.br/fnet/publico/visualizarDocumento?id=769277", "reference_date": "2024-10-31", "version": "1", "page": 49, "clause": "5.1", "excerpt": "5.1. O Índice de Subordinação será a relação mínima a ser observada entre o valor das  subclasses das Cotas Subordinadas Júnior e o Patrimônio Líquido da Classe, a qual deverá,  diariamente, representar o percentual mínimo de 10% (dez por cento). Isso significa que, no  mínimo, 10% (dez por cento) do Patrimônio Líquido da Classe deve ser representado por Cotas  Subordinadas em circulação.", "sha256": "4cb541cb8eabdb38a65a53759ba645963500d51a8c38074beafedb4e470baaa9", "verification": "primary_passage"}, {"document_id": "769277", "title": "Regulamento", "url": "https://fnet.bmfbovespa.com.br/fnet/publico/visualizarDocumento?id=769277", "reference_date": "2024-10-31", "version": "1", "page": 29, "clause": "11.1", "excerpt": "11.1. A subclasse de Cotas Seniores da Classe terá um índice de subordinação correspondente  à relação mínima a ser observada entre o valor das Cotas Subordinadas Júnior e o Patrimônio  Líquido da Classe à qual pertence, que será diariamente calculado pela Administradora e  monitorada pela Gestora. As regras de cálculo e os procedimentos aplicáveis na hipótese de  desenquadramento do Índice de Subordinação encontram-se descritos no respectivo Anexo da  Classe Única.", "sha256": "4cb541cb8eabdb38a65a53759ba645963500d51a8c38074beafedb4e470baaa9", "verification": "primary_passage"}, {"document_id": "769277", "title": "Regulamento", "url": "https://fnet.bmfbovespa.com.br/fnet/publico/visualizarDocumento?id=769277", "reference_date": "2024-10-31", "version": "1", "page": 59, "clause": "13.2", "excerpt": "13.2. A ocorrência de qualquer das seguintes hipóteses constituirá Evento de Avaliação:
(i) Em caso de insolvência da Administradora ou Gestora;
(ii) Em caso de verificação, a qualquer tempo, de descumprimento superveniente de  quaisquer dos limites de concentração estabelecidos nos incisos (viii) e (ix) da  Cláusula 8.1 acima;
(iii) Em caso de verificação, a qualquer tempo, de que 10% (dez por cento) ou mais do  montante total dos Direitos Creditórios não atendiam aos Critérios de Elegibilidade e às  Condições de Cessão na respectivas Datas de Aquisição;
(iv) Em caso de inobservância, pela Administradora e/ou pela Gestora de suas obrigações  previstas neste Anexo e no Regulamento, desde que, se notificado por escrito pela  Administradora e/ou pela Gestora, conforme o caso, para sanar ou justificar o  descumprimento, não o faça no período máximo de 2 (dois) Dias Úteis contado do  recebimento da referida notificação;
(v) rebaixamento da classificação de risco das Cotas Seniores em circulação (a) a qualquer  tempo, em 3 (três) níveis abaixo da classificação de risco originalmente atribuída, ou (2)  após uma única revisão de classificação de risco ou após 2 (duas) revisões consecutivas,  em 2 (dois) níveis abaixo da classificação de risco originalmente atribuída, conforme  aplicável;
(vi) desenquadramento da Alocação Mínima por mais de 30 (trinta) Dias Úteis consecutivos  sem que haja a correspondente regularização neste período;
(vii) verificação de Patrimônio Líquido Negativo;
(viii) Utilização dos recursos do Fundo em desconformidade com a respectiva Ordem de  Alocação de Recursos;
(ix) desenquadramento de Índice de Subordinação por um período superior ao previsto na  Cláusula 5.1 acima;", "sha256": "4cb541cb8eabdb38a65a53759ba645963500d51a8c38074beafedb4e470baaa9", "verification": "primary_passage"}]

[{"document_id": "1240668", "title": "Regulamento", "url": "https://fnet.bmfbovespa.com.br/fnet/publico/visualizarDocumento?id=1240668", "reference_date": "2026-02-24", "version": "1", "page": 14, "clause": "3.19.1", "excerpt": "3.19.1. A Gestora deverá apurar mensalmente, na Data de Verificação, a observância dos  seguintes limites de concentração, considerando-se o patrimônio líquido do Fundo do último Dia  Útil do mês anterior, conforme informações recebidas pela Administradora, pelo Custodiante e/ou  pelos Cedentes, conforme aplicável:
(i) a carteira de Direitos Creditórios do Fundo deverá manter prazo médio máximo de 180  (cento e oitenta) dias, devendo tal cálculo levar em consideração a quantidade de dias entre a data  aplicável e as datas de vencimentos, e os valores ponderados de cada parcela dos respectivos  Direitos Creditórios, conforme aplicável;
(ii) o Valor Presente dos Direitos Creditórios- Duplicatas devidos por um Devedor - Duplicatas  será limitado a 3,5% (três inteiros e cinco décimos por cento) do patrimônio líquido do Fundo,  exceto para os Devedores Especiais, cujo limite de concentração poderá ser de até 5% (cinco por  cento), a ser verificado considerando-se pro forma cada cessão de Direitos Creditórios – Duplicatas  ao Fundo, conforme consulta de Devedores por grupo econômico mais recente realizada pela  Gestora, sendo que os limites de concentração por um Devedor – Duplicatas ou por um Devedor  Especial poderão ser aumentados mediante solicitação do Cedente Altomax, utilizando a soma dos  limites dispostos acima, individualmente, conforme aplicável, com o percentual apurado de Excesso  de Subordinação disponível na Data de Aquisição;
(iii) o Valor Presente dos Direitos Creditórios – Duplicatas devidos pelos 10 (dez) maiores  Devedores, excetuados os Devedores Especiais, será limitado a 25% (vinte e cinco por cento) do  patrimônio líquido do Fundo, a ser verificado considerando-se pro forma cada cessão de Direitos  Creditórios – Duplicatas ao Fundo, conforme consulta de Devedores por grupo econômico mais  recente realizada pela Gestora, sendo que, na hipótese de aporte nas Cotas Subordinadas Júnior, o  limite de concentração pelos 10 (dez) maiores Devedores poderá ser aumentado no limite do  Excesso de Subordinação. No caso dos Direitos Creditórios – Recebíveis de Cartão, não haverá  limitação de concentração por Devedor; e
(iv) o Fundo deverá cumprir com a Alocação Mínima e com a Alocação Mínima Adicional.", "sha256": "9b988d074a3d7ec6f89b71b4d8860ad798f2e5c0d6db2fbb29d6709054313291", "verification": "primary_passage"}, {"document_id": "1240668", "title": "Regulamento", "url": "https://fnet.bmfbovespa.com.br/fnet/publico/visualizarDocumento?id=1240668", "reference_date": "2026-02-24", "version": "1", "page": 10, "clause": "", "excerpt": "(g) o Valor Presente dos Direitos Creditórios – Duplicatas devidos por um Devedor –  Duplicatas será limitado a 3,5% (três inteiros e cinco décimos por cento) do patrimônio líquido  do Fundo, exceto para Devedores Especiais, cujo limite de concentração poderá ser de até 5%  (cinco por cento) e para o Devedor Especial EBAZAR.COM.BR. LTDA, inscrito no CNPJ sob o nº
 03.007.331/0008-18, cujo limite será de até 10% (dez por cento), a ser verificado  considerando-se pro forma cada cessão de Direitos Creditórios – Duplicatas ao Fundo, conforme  consulta de Devedores por grupo econômico mais recente realizada pela Gestora, sendo que os  limites de concentração por um Devedor – Duplicatas ou por um Devedor Especial poderá ser  aumentados mediante solicitação do Cedente Altomax, utilizando a soma dos limites dispostos  acima, individualmente, conforme aplicável, com o percentual apurado de Excesso de  Subordinação disponível na Data de Aquisição. No caso dos Direitos Creditórios - Recebíveis de  Cartão e dos Direitos Creditórios - Adicionais, não haverá limitação de concentração por  Devedor;", "sha256": "9b988d074a3d7ec6f89b71b4d8860ad798f2e5c0d6db2fbb29d6709054313291", "verification": "primary_passage"}, {"document_id": "1240668", "title": "Regulamento", "url": "https://fnet.bmfbovespa.com.br/fnet/publico/visualizarDocumento?id=1240668", "reference_date": "2026-02-24", "version": "1", "page": 10, "clause": "", "excerpt": "(h) o Valor Presente dos Direitos Creditórios – Duplicatas devidos pelos 10 (dez) maiores  Devedores, excetuados os Devedores Especiais, será limitado a 25% (vinte e cinco por cento)  do patrimônio líquido do Fundo, a ser verificado considerando-se pro forma cada cessão de  Direitos Creditórios – Duplicatas ao Fundo, conforme consulta de Devedores por grupo  econômico mais recente realizada pela Gestora, sendo que, na hipótese de aporte nas Cotas  Subordinadas Júnior, o limite de concentração pelos 10 (dez) maiores Devedores poderá ser  aumentado no limite do Excesso de Subordinação. No caso dos Direitos Creditórios – Recebíveis  de Cartão e dos Direitos Creditórios - Adicionais, não haverá limitação de concentração por  Devedor;", "sha256": "9b988d074a3d7ec6f89b71b4d8860ad798f2e5c0d6db2fbb29d6709054313291", "verification": "primary_passage"}]

[{"document_id": "1240668", "title": "Regulamento", "url": "https://fnet.bmfbovespa.com.br/fnet/publico/visualizarDocumento?id=1240668", "reference_date": "2026-02-24", "version": "1", "page": 81, "clause": "", "excerpt": "“Alocação Mínima” significa o percentual mínimo de 67% (sessenta e sete por cento) do  patrimônio líquido a ser mantido em Direitos Creditórios após 180  (cento e oitenta) dias contados da 1ª Data de Integralização.", "sha256": "9b988d074a3d7ec6f89b71b4d8860ad798f2e5c0d6db2fbb29d6709054313291", "verification": "primary_passage"}, {"document_id": "1240668", "title": "Regulamento", "url": "https://fnet.bmfbovespa.com.br/fnet/publico/visualizarDocumento?id=1240668", "reference_date": "2026-02-24", "version": "1", "page": 81, "clause": "", "excerpt": "“Alocação Mínima significa o percentual mínimo de 85% (oitenta e cinco por cento) do  Adicional” patrimônio líquido a ser mantido em Direitos Creditórios após  decorridos 210 (duzentos e dez) dias a contar da 1ª Data de  Integralização.", "sha256": "9b988d074a3d7ec6f89b71b4d8860ad798f2e5c0d6db2fbb29d6709054313291", "verification": "primary_passage"}, {"document_id": "1240668", "title": "Regulamento", "url": "https://fnet.bmfbovespa.com.br/fnet/publico/visualizarDocumento?id=1240668", "reference_date": "2026-02-24", "version": "1", "page": 14, "clause": "3.19.1", "excerpt": "3.19.1. A Gestora deverá apurar mensalmente, na Data de Verificação, a observância dos  seguintes limites de concentração, considerando-se o patrimônio líquido do Fundo do último Dia  Útil do mês anterior, conforme informações recebidas pela Administradora, pelo Custodiante e/ou  pelos Cedentes, conforme aplicável:
(i) a carteira de Direitos Creditórios do Fundo deverá manter prazo médio máximo de 180  (cento e oitenta) dias, devendo tal cálculo levar em consideração a quantidade de dias entre a data  aplicável e as datas de vencimentos, e os valores ponderados de cada parcela dos respectivos  Direitos Creditórios, conforme aplicável;
(ii) o Valor Presente dos Direitos Creditórios- Duplicatas devidos por um Devedor - Duplicatas  será limitado a 3,5% (três inteiros e cinco décimos por cento) do patrimônio líquido do Fundo,  exceto para os Devedores Especiais, cujo limite de concentração poderá ser de até 5% (cinco por  cento), a ser verificado considerando-se pro forma cada cessão de Direitos Creditórios – Duplicatas  ao Fundo, conforme consulta de Devedores por grupo econômico mais recente realizada pela  Gestora, sendo que os limites de concentração por um Devedor – Duplicatas ou por um Devedor  Especial poderão ser aumentados mediante solicitação do Cedente Altomax, utilizando a soma dos  limites dispostos acima, individualmente, conforme aplicável, com o percentual apurado de Excesso  de Subordinação disponível na Data de Aquisição;
(iii) o Valor Presente dos Direitos Creditórios – Duplicatas devidos pelos 10 (dez) maiores  Devedores, excetuados os Devedores Especiais, será limitado a 25% (vinte e cinco por cento) do  patrimônio líquido do Fundo, a ser verificado considerando-se pro forma cada cessão de Direitos  Creditórios – Duplicatas ao Fundo, conforme consulta de Devedores por grupo econômico mais  recente realizada pela Gestora, sendo que, na hipótese de aporte nas Cotas Subordinadas Júnior, o  limite de concentração pelos 10 (dez) maiores Devedores poderá ser aumentado no limite do  Excesso de Subordinação. No caso dos Direitos Creditórios – Recebíveis de Cartão, não haverá  limitação de concentração por Devedor; e
(iv) o Fundo deverá cumprir com a Alocação Mínima e com a Alocação Mínima Adicional.", "sha256": "9b988d074a3d7ec6f89b71b4d8860ad798f2e5c0d6db2fbb29d6709054313291", "verification": "primary_passage"}]

[{"document_id": "1240668", "title": "Regulamento", "url": "https://fnet.bmfbovespa.com.br/fnet/publico/visualizarDocumento?id=1240668", "reference_date": "2026-02-24", "version": "1", "page": 43, "clause": "14.1", "excerpt": "14.1. A Gestora deverá orientar a Administradora a constituir uma Reserva de Amortização,  composta pela Reserva de Amortização Sênior e pela Reserva de Amortização Mezanino, esta  última, caso aplicável, para amortização das Cotas Seniores e das Cotas Subordinadas Mezanino,  respectivamente, correspondentes aos valores aportados ao Fundo, acrescidos dos rendimentos  calculados de acordo com os respectivos Benchmarks, conforme os termos e condições  estabelecidos nos respectivos Apêndices, formada por recursos provenientes das liquidações dos  Direitos Creditórios da carteira do Fundo, mantendo-os aplicados em Ativos Financeiros, mediante  ordem encaminhada à Administradora. A Reserva de Amortização deverá corresponder sempre, no  mínimo, à projeção dos montantes devidos a título de amortização e rendimentos dos titulares das  Cotas Seniores e aos titulares das Cotas Subordinadas Mezanino na próxima Data de Pagamento,  observado que, a partir de 30 (trinta) dias corridos antes de cada Data de Pagamento de  amortização de Cotas ou de rendimentos e até 2 (dois) Dias Úteis antes de cada Data de  Pagamento de amortização de Cotas ou de rendimentos, conforme o caso, conforme previstas nos  respectivos Apêndices, o Fundo deverá manter em disponibilidades (líquidas de Reserva de  Despesas, de quaisquer impostos, taxas, contribuições, encargos ou despesas de qualquer  natureza) soma equivalente à projeção dos montantes devidos a título de amortização e  rendimentos aos titulares das Cotas Seniores e aos titulares das Cotas Subordinadas Mezanino,  caso haja, nas próximas 2 (duas) Datas de Pagamento.", "sha256": "9b988d074a3d7ec6f89b71b4d8860ad798f2e5c0d6db2fbb29d6709054313291", "verification": "primary_passage"}, {"document_id": "1240668", "title": "Regulamento", "url": "https://fnet.bmfbovespa.com.br/fnet/publico/visualizarDocumento?id=1240668", "reference_date": "2026-02-24", "version": "1", "page": 43, "clause": "14.1.1", "excerpt": "14.1.1. Para fins de cálculo da Reserva de Amortização, na forma do disposto no Artigo 14.1, as  amortizações de Cotas terão seus valores calculados conforme o disposto no Artigo 13.9 acima.", "sha256": "9b988d074a3d7ec6f89b71b4d8860ad798f2e5c0d6db2fbb29d6709054313291", "verification": "primary_passage"}, {"document_id": "1240668", "title": "Regulamento", "url": "https://fnet.bmfbovespa.com.br/fnet/publico/visualizarDocumento?id=1240668", "reference_date": "2026-02-24", "version": "1", "page": 51, "clause": "18.1", "excerpt": "18.1. São considerados Eventos de Avaliação quaisquer dos seguintes eventos:
(i) não divulgação, pela Gestora, do Relatório de Monitoramento, desde que no prazo de 15
 (quinze) Dias Úteis contados da respectiva Data de Envio do Relatório de Monitoramento o envio  do referido relatório não seja sanado pela Gestora;
(ii) desenquadramento dos limites de concentração da carteira do Fundo indicados no Artigo
 3.18, deste Regulamento, sem que haja a correspondente regularização no prazo de 10 (dez) Dias  Úteis após o envio da comunicação da Gestora ao Cedente Altomax sobre o desenquadramento;
(iii) desenquadramento dos Índices de Monitoramento em qualquer Data de Verificação, por 2
 (duas) vezes seguidas ou 3 (três) vezes alternadas em um período de 2 (dois) anos, exceto pelo  Índice de Repasse, conforme item (xii) abaixo;
(iv) desenquadramento ou não constituição da Reserva de Despesas;
(v) desenquadramento ou não constituição da Reserva de Amortização;
(vi) amortização de Cotas em desacordo com o disposto neste Regulamento;
(vii) desenquadramento dos Índices de Subordinação sem (a) a recomposição pelo Cotista  Subordinado Júnior no prazo previsto neste Regulamento; ou (b) que o Fundo tenha recursos  disponíveis para realizar a amortização extraordinária das Cotas Seniores e/ou das Cotas  Subordinadas Mezanino, caso aplicável, nos termos do item (vi) do Artigo 16.1.1 deste", "sha256": "9b988d074a3d7ec6f89b71b4d8860ad798f2e5c0d6db2fbb29d6709054313291", "verification": "primary_passage"}]

[{"document_id": "1278972", "title": "Regulamento", "url": "https://fnet.bmfbovespa.com.br/fnet/publico/visualizarDocumento?id=1278972", "reference_date": "2026-07-27", "version": "1", "page": 14, "clause": "", "excerpt": "(vi) após o Fundo atingir uma concentração nos 10 (dez) maiores Devedores, considerando-se  em tal conceito Devedores do mesmo Grupo Econômico, os demais Devedores deverão observar um  limite de concentração individual do Valor Presente dos Direitos creditórios de até (a) 3,5% (três  inteiros e cinco décimos por cento) do patrimônio líquido do Fundo nos 2 (dois) primeiros anos; (b)  4% (quatro por cento) do patrimônio líquido do Fundo no 3º (terceiro) ano; e (c) 5% (cinco por  cento) do patrimônio líquido do Fundo no 4º (quarto) ano, a ser verificado considerando-se pro  forma cada cessão de Direitos Creditórios ao Fundo. A partir do 5º (quinto) ano, esses limites de  concentração não serão mais aplicáveis; o; e", "sha256": "236eb6e1679fde05e5f471093422a939e5c1e19c306dc9c6e1b5123d1a8cda16", "verification": "primary_passage"}, {"document_id": "1278972", "title": "Regulamento", "url": "https://fnet.bmfbovespa.com.br/fnet/publico/visualizarDocumento?id=1278972", "reference_date": "2026-07-27", "version": "1", "page": 13, "clause": "3.16.1", "excerpt": "3.16.1. A Gestora deverá apurar mensalmente, na Data de Verificação, a observância dos seguintes  limites de concentração, considerando-se o patrimônio líquido do Fundo do último Dia Útil do mês  anterior, conforme informações recebidas pela Administradora, pelo Custodiante e/ou pelos  Cedentes, conforme aplicável:
(i) a carteira do Fundo, considerando pro forma a aquisição dos Direitos Creditórios em  questão, deverá manter prazo médio máximo de 48 (quarenta e oito) meses, devendo tal cálculo  levar em consideração a quantidade de dias entre a data de cálculo aplicável e as datas de  vencimentos, e os respectivos valores ponderados de cada parcela dos Direitos Creditórios, conforme  aplicável;
(ii) os Contratos de Locação de Equipamentos deverão, na respectiva Data de Aquisição, ter  um prazo remanescente anterior à Data de Amortização Final de Cotas Seniores, exceto quando pro  forma o saldo do somatório das parcelas de Direitos Creditórios cedidos com vencimento anterior à  Data de Amortização Final de Cotas Seniores, somado com o saldo disponível em caixa do Fundo,  atinja montante superior ao saldo devedor das Cotas Seniores e Cotas Subordinadas Mezanino;
(iii) o Valor Presente dos Direitos Creditórios devidos por Devedor do mesmo Grupo Econômico,  será limitado a 15% (quinze por cento) do patrimônio líquido do Fundo, durante os 4 (quatro)  primeiros anos, a ser verificado considerando-se pro forma cada cessão de Direitos Creditórios ao  Fundo, até que se inicie a Amortização Sequencial. A partir do 5º (quinto) ano, esses limites de  concentração não serão mais aplicáveis;
(iv) o Valor Presente dos Direitos Creditórios devidos pelos 5 (cinco) maiores Devedores,  considerando-se em tal conceito Devedores do mesmo Grupo Econômico, será limitado a (a) 40%  (quarenta por cento) do patrimônio líquido do Fundo nos 2 (dois) primeiros anos; (b) 45% (quarenta  e cinco por cento) do patrimônio líquido do Fundo no 3º (terceiro) ano; e (c) 55% (cinquenta e cinco  cento) do patrimônio líquido do Fundo no 4º (quarto) ano, a ser verificado considerando-se pro  forma cada cessão de Direitos Creditórios ao Fundo, até que se inicie a Amortização Sequencial. A  partir do 5º (quinto) ano, esses limites de concentração não serão mais aplicáveis;
(v) o Valor Presente dos Direitos Creditórios devidos pelos 10 (dez) maiores Devedores,  considerando-se em tal conceito Devedores do mesmo Grupo Econômico, será limitado a (a) 62%  (sessenta e dois por cento) do patrimônio líquido do Fundo nos 2 (dois) primeiros anos; (b) 70%  (setenta por cento) do patrimônio líquido do Fundo no 3º (terceiro) ano; e (c) 90% (noventa por  cento) do patrimônio líquido do Fundo no 4º (quarto) ano, a ser verificado considerando-se pro  forma cada cessão de Direitos Creditórios ao Fundo. A partir do 5º (quinto) ano, esses limites de", "sha256": "236eb6e1679fde05e5f471093422a939e5c1e19c306dc9c6e1b5123d1a8cda16", "verification": "primary_passage"}, {"document_id": "1278972", "title": "Regulamento", "url": "https://fnet.bmfbovespa.com.br/fnet/publico/visualizarDocumento?id=1278972", "reference_date": "2026-07-27", "version": "1", "page": 8, "clause": "", "excerpt": "(ix) após o Fundo atingir uma concentração nos 10 (dez) maiores Devedores, considerando-se  em tal conceito Devedores do mesmo Grupo Econômico, os demais Devedores deverão observar um  limite de concentração individual do Valor Presente dos Direitos creditórios de até 3,5% (três inteiros  e cinco décimos por cento) do patrimônio líquido do Fundo, a ser verificado considerando-se pro  forma cada cessão de Direitos Creditórios ao Fundo;", "sha256": "236eb6e1679fde05e5f471093422a939e5c1e19c306dc9c6e1b5123d1a8cda16", "verification": "primary_passage"}]

[{"document_id": "1223029", "title": "Regulamento", "url": "https://fnet.bmfbovespa.com.br/fnet/publico/visualizarDocumento?id=1223029", "reference_date": "2026-06-08", "version": "1", "page": 62, "clause": "9.1", "excerpt": "9.1 Observada a ordem de alocação de recursos prevista no Capítulo 12 deste Anexo Descritivo, a Administradora deverá, na forma abaixo estabelecida, constituir a Reserva de Amortização, de modo a proporcionar liquidez para o pagamento das amortizações das Cotas Seniores e das Cotas Subordinadas Mezanino:
(i) até 30 (trinta) dias de cada data de amortização ou data de resgate de  Cotas Seniores e Cotas Subordinadas Mezanino, o saldo da Reserva de  Amortização deverá ser equivalente a 50% (cinquenta por cento) do valor integral  da amortização ou resgate atualizado até a data da constituição da reserva; e
(ii) até 7 (sete) Dias Úteis antes de cada data de amortização ou data de  resgate de Cotas Seniores e Cotas Subordinadas Mezanino, o saldo da Reserva  de Amortização deverá ser equivalente a 100% (cem por cento) do valor integral  da amortização ou resgate atualizado até a data da constituição da reserva.", "sha256": "5a1a0dd19fe6ebebb9fdad76c53df5005babe39306307c2194330644de315967", "verification": "primary_passage"}, {"document_id": "1223029", "title": "Regulamento", "url": "https://fnet.bmfbovespa.com.br/fnet/publico/visualizarDocumento?id=1223029", "reference_date": "2026-06-08", "version": "1", "page": 62, "clause": "9.4", "excerpt": "9.4 Na hipótese de a Classe deixar de atender a Reserva de Amortização ou a Reserva de Despesas e Encargos, a Administradora, por conta e ordem da Classe, deverá destinar todos os recursos da Classe, em moeda corrente nacional, para a recomposição da Reserva de Amortização e da Reserva de Despesas e Encargos, observada a ordem de alocação de recursos prevista no Capítulo 12 deste Anexo Descritivo.", "sha256": "5a1a0dd19fe6ebebb9fdad76c53df5005babe39306307c2194330644de315967", "verification": "primary_passage"}, {"document_id": "1223029", "title": "Regulamento", "url": "https://fnet.bmfbovespa.com.br/fnet/publico/visualizarDocumento?id=1223029", "reference_date": "2026-06-08", "version": "1", "page": 64, "clause": "", "excerpt": "(1) pagamento de despesas e encargos de responsabilidade da  Classe, devidos nos termos deste Regulamento e da legislação aplicável;
 (2) constituição ou recomposição da Reserva de Amortização e da  Reserva de Despesas e Encargos;
 (3) Amortizações programadas e/ou resgate das Cotas Seniores,  observados os termos e condições deste Regulamento;
 (4) Amortizações programadas e/ou resgate das Cotas Subordinadas  Mezanino, observados os termos e condições deste Regulamento;
 (5) Amortização e ou resgate de Cotas Subordinadas Júnior,  observados os limites, os termos e as condições deste Regulamento;
 (6) aquisição de Direitos Creditórios; e  (7) aquisição de Ativos Financeiros.", "sha256": "5a1a0dd19fe6ebebb9fdad76c53df5005babe39306307c2194330644de315967", "verification": "primary_passage"}]

[{"document_id": "1276588", "title": "Regulamento", "url": "https://fnet.bmfbovespa.com.br/fnet/publico/visualizarDocumento?id=1276588", "reference_date": "2026-08-04", "version": "1", "page": 33, "clause": "7.4.3", "excerpt": "7.4.3. Nos termos do § 3º e §7º do artigo 45 do Anexo Normativo II da Resolução CVM 175, a Classe poderá adquirir Direitos Creditórios e/ou Ativos Financeiros de um mesmo Devedor, ou de coobrigação de uma mesma pessoa ou entidade, que excedam 20% (vinte por cento) de seu Patrimônio Líquido, desde que observadas as exigências abaixo:", "sha256": "dc85b0982f00e4ac6c29d503d98d00ef6bf58635951c800e10fb6158153ebc34", "verification": "primary_passage"}, {"document_id": "1276588", "title": "Regulamento", "url": "https://fnet.bmfbovespa.com.br/fnet/publico/visualizarDocumento?id=1276588", "reference_date": "2026-08-04", "version": "1", "page": 37, "clause": "", "excerpt": "xiii. Devedores e/ou avalistas, conforme o caso, não poderão ter pendências em órgãos de  proteção de crédito superior a 5% (cinco por cento) do valor do crédito do agronegócio  objeto do respectivo Ativo Financeiro, sendo que este não poderá ultrapassar o montante  global de R$ 5.000,00 (cinco mil reais), salvo se previamente aprovado por escrito pela  Gestora, com base no Parecer de Crédito;
xiv. Devedores não poderão ter nenhuma operação de crédito em atraso em montante  superior a R$ 5.000,00 (cinco mil reais), salvo se previamente aprovado por escrito pela  Gestora, com base no Parecer de Crédito, e/ou prejuízo no sistema ﬁnanceiro nacional, o  que será atestado por meio de consulta ao SCR;
xv. Devedores não poderão ser parte do, ou pertencer ao, Grupo Econômico dos Cedentes;
xvi. Direitos Creditórios deverão ter sido originados no mercado local e ter o seu valor  expresso em moeda corrente nacional;
xvii. Direitos Creditórios deverão observar a Concentração Máxima por Estado;
xviii. As taxas e prazos de cada Direito Creditório reﬂetem o risco do devedor;
xix. O enquadramento por Estado será determinado, preferencialmente, a partir da  localização da área beneﬁciada, podendo, nos Direitos Creditórios oriundos de Operações  de Crédito Produtor Rural, ser deﬁnido com base na residência do Produtor Rural;
xx. Limites de concentração por Estado não serão aplicados para os Direitos Creditórios  oriundos de Operações de Crédito Farm Equity e para os Direitos Creditórios oriundos  de Operações de Crédito cuja área beneﬁciada é irrigada;
xxi. Deverão observar a Taxa Média Mínima de Cessão de 1,65% (um vírgula sessenta e cinco  por cento) ao mês, apurada com base no somatório dos Direitos Creditórios Adquiridos e  ainda integrantes da Carteira da Classe;
xxii. Em relação aos Direitos Creditórios representados por CPR-Fs, as CPR-Fs deverão ser  registradas na CERC ou na B3, conforme aplicável;
xxiii. Direitos Creditórios não poderão ser devidos por Devedores que tenham renegociado o  pagamento de outros Direitos Creditórios já cedidos à Classe e que ainda não tenham  sido devidamente quitados pelos correspondentes Devedores;
xxiv. Direitos Creditórios não poderão ser originados por Devedores que atuam na cadeia  produtiva do tabaco, fumo e derivados;
xxv. Direitos Creditórios de um único título poderão ser alocados em mais de um tipo de CNAE  relacionado a atividades que integram a cadeia do agronegócio, ocupando, assim, limites  de concentração por cultura diferentes, que serão identiﬁcados conforme o período do  ano e prazo de vencimento dos Direitos Creditórios;
xxvi. Deverão ser originados de acordo com a política de crédito da Nagro anexa ao Contrato  de Cobrança Extrajudicial;
xxvii. Após 150 (cento e cinquenta) dias corridos contados da data da primeira integralização  de Cotas da Classe, os Direitos Creditórios deverão observar a Concentração Máxima por  Estado, a Concentração Máxima por Cultura, e a Concentração Mínima por Linha de  Crédito, observado o Fator Redutor dos Limites de Concentração por Cultura e Estado  previsto no Anexo VIII, observadas as limitações previstas no Anexo IX;
xxviii. Após 150 (cento e cinquenta) dias corridos contados da data da primeira integralização  de Cotas da Classe, a concentração por linha de crédito deverá observar os limites de", "sha256": "dc85b0982f00e4ac6c29d503d98d00ef6bf58635951c800e10fb6158153ebc34", "verification": "primary_passage"}, {"document_id": "1276588", "title": "Regulamento", "url": "https://fnet.bmfbovespa.com.br/fnet/publico/visualizarDocumento?id=1276588", "reference_date": "2026-08-04", "version": "1", "page": 39, "clause": "", "excerpt": "i. A exposição máxima por sacado, considerando o valor de aquisição do Direito Creditório,  deve ser de 0,75% do patrimônio líquido da Classe ou R$ 1.250.000,00 (um milhão,  duzentos e cinquenta mil reais), o que for maior;
 ii. Deverá observar o limite de concentração de 10% dos Direitos Creditórios originários de  operações de revenda, podendo tal limite atingir até 15% do total do patrimônio líquido  da Classe com ou sem coobrigação se tratar-se de operações cuja revenda for companhia  de capital aberto ou cuja classiﬁcação de risco for AAA+, em escala nacional;
 iii. A carteira de investimentos em Direitos Creditórios oriundos de Operações para  Antecipação de Recebíveis deverá observar coobrigação mínima de 50% (cinquenta por  cento) da revenda do Direito Creditório cedido;
 iv. Deverão observar o prazo máximo de vencimento de 18 (dezoito) meses ou a data de  vencimento das Cotas Seniores mais longas, sendo válido apenas o menor prazo;
 v. Deverão contar com nota ﬁscal de produto, quando emitida, e/ou outros títulos  representativos de crédito, emitidos pelo(s) Cedente(s) em nome do(s) Devedor(es)
 (sacado), com data de emissão inferior a 180 (cento e oitenta) dias da data de cessão;
 39", "sha256": "dc85b0982f00e4ac6c29d503d98d00ef6bf58635951c800e10fb6158153ebc34", "verification": "primary_passage"}]

[{"document_id": "1276588", "title": "Regulamento", "url": "https://fnet.bmfbovespa.com.br/fnet/publico/visualizarDocumento?id=1276588", "reference_date": "2026-08-04", "version": "1", "page": 70, "clause": "", "excerpt": "por cento) do Patrimônio Líquido, em desconformidade com as Condições de Cessão  e Critérios de Elegibilidade estabelecidos neste Regulamento, e referido evento não  seja sanado em até 15 (quinze) Dias Úteis a contar da data em que o índice de 2%  (dois por cento) seja atingido;
 xii. O não envio pelo Agente de Cobrança à Gestora, conforme o caso, das informações  necessárias para os cálculos dos Índices de Monitoramento, desde que não seja  sanado dentro de 10 (dez) Dias Úteis;
 xiii. Pagamentos dos recursos da Classe em desconformidade com a respectiva Ordem  de Alocação de Recursos que não seja sanada em até 5 (cinco) Dias Úteis contados  da caracterização do referido evento;
 xiv. Não revisão da classiﬁcação de risco das Cotas pela Administradora em  frequência, no mínimo, trimestral;
 xv. Na hipótese de desenquadramento da Alocação Mínima de Investimento, que não  seja sanada em até 20 (vinte) Dias Úteis contados da ocorrência do  desenquadramento;
 xvi. Na hipótese de: (i) inexigibilidade dos Direitos Creditórios adquiridos em decorrência  de ordem judicial e/ou de qualquer autoridade governamental; ou (ii) ocorrência de  qualquer questionamento judicial ou administrativo de órgão governamental ou  regulatório, para incluir alteração legislativa ou regulamentar, bem como abertura de  inquérito, processo administrativo ou outro que, em quaisquer dos casos (i) ou (ii)  acima, tenha como objeto:
 (1) o questionamento judicial sobre a possibilidade da Classe adquirir os Direitos  Creditórios, ou sobre a validade ou legitimidade da Carteira da Classe; e/ou (2) matéria  que potencialmente possa trazer qualquer restrição, ônus ou custo que não estivesse  originalmente previsto na estruturação da Classe, ou gerar impacto na rentabilidade  prevista para a Classe, não sanados por período superior a 20 (vinte) Dias Úteis;
 xvii. Na hipótese de serem realizados pagamentos de qualquer natureza aos titulares de  Cotas Subordinadas Júnior em desacordo com o disposto neste Anexo;
 xviii. Caso as Razões de Garantia ﬁquem desenquadradas e não sejam atendidas dentro  do prazo estabelecido para o reenquadramento nos termos deste Anexo;
xix. Em caso de mudança, substituição ou renúncia da Gestora;
 xx. Em caso de descumprimento da Taxa Média Mínima de Cessão, desde que não  reenquadrada em até 120 (cento e vinte) dias. Neste caso, a Gestora deverá notiﬁcar  imediatamente a Administradora quando constatado tal Evento de Avaliação para  que esta tome as medidas previstas no Parágrafo Primeiro abaixo;
 xxi. Rebaixamento de dois ou mais notas da Classe de Cotas Sênior A da Classe pela  agência de risco.
 xxii. Em caso de desenquadramento dos limites de exposição por linha de crédito  previstos no Anexo não reenquadrado em até 30 (trinta) dias após o término de cada  mês, exceto para os primeiros 150 (cento e cinquenta) dias corridos após a primeira  integralização da Classe;
xxiii. Em caso de ocorrência de um Evento de Insolvência;
 xxiv. Na hipótese de ocorrerem alterações regulatórias e/ou governamentais que venham  a modiﬁcar, substituir ou suprimir a eﬁcácia, validade ou existência dos títulos e/ou  Documentos Comprobatórios que lastreiam os Direitos Creditórios adquiridos pela  Classe;
 70", "sha256": "dc85b0982f00e4ac6c29d503d98d00ef6bf58635951c800e10fb6158153ebc34", "verification": "primary_passage"}, {"document_id": "1276588", "title": "Regulamento", "url": "https://fnet.bmfbovespa.com.br/fnet/publico/visualizarDocumento?id=1276588", "reference_date": "2026-08-04", "version": "1", "page": 33, "clause": "7.4.2.1", "excerpt": "7.4.2.1. Observado o disposto no item 7.4.1 acima, a parcela do Patrimônio Líquido da Classe deverá representada por Direitos Creditórios Elegíveis deverá ser de, no mínimo, mais de 50% (cinquenta por cento) e, no máximo, até 100% (cem por cento).", "sha256": "dc85b0982f00e4ac6c29d503d98d00ef6bf58635951c800e10fb6158153ebc34", "verification": "primary_passage"}, {"document_id": "1276588", "title": "Regulamento", "url": "https://fnet.bmfbovespa.com.br/fnet/publico/visualizarDocumento?id=1276588", "reference_date": "2026-08-04", "version": "1", "page": 38, "clause": "", "excerpt": "i. Devedores Produtores Rurais Pessoas Físicas deverão ter no mínimo 2 (dois) anos de  experiência na atividade;
 ii. Deverão ser representados por Instrumentos de Crédito Elegíveis, com destinação de  recursos à atividade do setor do agronegócio;
 iii. Considerando o valor de aquisição do Direito Creditório, deverão observar a exposição  máxima de 0,25% do patrimônio líquido da Classe ou R$ 300.000,00 (trezentos mil reais),  o que for maior, de principal e/ou valor de aquisição do título, por Devedor e/ou respectivo  Grupo Econômico, devendo observar o prazo máximo de vencimento de 30 (trinta) meses  ou data de vencimento das Cotas Seniores com prazo de vencimento mais longo em  circulação, sendo o prazo máximo limitado dos dois o menor;
 iv. A concessão de novos Direitos Creditórios, a partir de 04 de agosto de 2026, Deverão  observar a Taxa Mínima de Cessão, por faixa de rating, conforme a tabela do  SUPLEMENTO IX - LIMITES DE EXPOSIÇÃO POR LINHA DE CRÉDITO, observada  ainda a taxa média mínima da carteira originada de Crédito Produtor Rural de 3,15% (três  inteiros e quinze centésimos por cento) ao mês;
 v. Deverão compreender o máximo de 45% (quarenta e cinco por cento) do Patrimônio  Líquido da Classe, somadas as faixas de rating AA, A, B e C,  vi. Para originações e revolvências a partir de 04 de agosto de 2026, serão permitidas com  devedores de rating AA, A, B e C, observados os limites e taxas mínimas por faixa do  SUPLEMENTO IX - LIMITES DE EXPOSIÇÃO POR LINHA DE CRÉDITO, sendo  vedadas originações e revolvências com devedores de rating D ou inferior..", "sha256": "dc85b0982f00e4ac6c29d503d98d00ef6bf58635951c800e10fb6158153ebc34", "verification": "primary_passage"}]

[{"document_id": "1276588", "title": "Regulamento", "url": "https://fnet.bmfbovespa.com.br/fnet/publico/visualizarDocumento?id=1276588", "reference_date": "2026-08-04", "version": "1", "page": 44, "clause": "", "excerpt": "i. os índices de atraso dispostos na tabela acima;
 ii. a Razão de Subordinação;
 iii. a Alocação Mínima de Investimento;
 iv. a Quantidade Mínima de Devedores;
 v. o Índice de Repasse dos Cedentes, que não deverá ser superior a 5% (cinco por cento);
 vi. o Índice de Resolução, o qual não deverá ser superior a 6% (seis por cento);
 vii. o Índice de Renegociação, que não deverá ser superior a 5% (cinco por cento)  viii. o Índice de Recompra, o qual não deverá ser superior a 5% (cinco por cento).", "sha256": "dc85b0982f00e4ac6c29d503d98d00ef6bf58635951c800e10fb6158153ebc34", "verification": "primary_passage"}, {"document_id": "1276588", "title": "Regulamento", "url": "https://fnet.bmfbovespa.com.br/fnet/publico/visualizarDocumento?id=1276588", "reference_date": "2026-08-04", "version": "1", "page": 57, "clause": "", "excerpt": "i. 15% (quinze por cento) de seu patrimônio representado por Cotas Subordinadas  Mezanino (“Subordinação Mínima Mezanino”);
 ii. 10% (dez por cento) de seu patrimônio representado por Cotas Subordinadas Júnior A e  Júnior B (“Proporção Mínima da Subordinada Júnior A e B”).", "sha256": "dc85b0982f00e4ac6c29d503d98d00ef6bf58635951c800e10fb6158153ebc34", "verification": "primary_passage"}]

[{"document_id": "1276588", "title": "Regulamento", "url": "https://fnet.bmfbovespa.com.br/fnet/publico/visualizarDocumento?id=1276588", "reference_date": "2026-08-04", "version": "1", "page": 66, "clause": "15.5", "excerpt": "15.5. Observada a Ordem de Alocação de Recursos, a Administradora também deverá constituir uma Reserva de Liquidez, por conta e ordem do Classe, equivalente a 100% (cem por cento) da Meta de PMT aplicável para cada uma das classes e séries de Cotas em Circulação", "sha256": "dc85b0982f00e4ac6c29d503d98d00ef6bf58635951c800e10fb6158153ebc34", "verification": "primary_passage"}, {"document_id": "1276588", "title": "Regulamento", "url": "https://fnet.bmfbovespa.com.br/fnet/publico/visualizarDocumento?id=1276588", "reference_date": "2026-08-04", "version": "1", "page": 69, "clause": "", "excerpt": "i. Caso a Classe deixe de efetuar o pagamento:
 a. integral de qualquer das Amortizações Programadas, na respectiva Data de  Amortização Programada,  b. integral dos Resgates das Cotas, na respectiva Data de Resgate de Cotas,  c. da Meta de Rentabilidade das Cotas nas respectivas datas e/ou  d. da Remuneração, calculada nos termos deste Regulamento;
 ii. Caso, 30 (trinta) dias antes de qualquer Data de Amortização Programada, o valor dos  recursos segregados na Reserva de Liquidez não corresponda no mínimo ao valor da  próxima Amortização Programada somada à da próxima Remuneração, conforme  disposto nas tabelas constantes nos respectivos Suplementos;
 iii. Caso, 10 (dez) dias antes de qualquer data de pagamento das despesas ordinárias da  Classe, o valor dos recursos segregados na Reserva de Caixa não corresponda no mínimo  ao valor das despesas ordinárias da Classe dos próximos 10 (dez) dias;
 iv. Caso seja veriﬁcado o desenquadramento de qualquer um dos Índices de Monitoramento,  exceto os Índices de Inadimplemento, observados os respectivos prazos de cura  previstos nos itens 10.1.3, 10.1.4 e 10.1.5 deste Anexo, conforme aplicável a cada Índice  de Monitoramento;
 v. Caso seja veriﬁcado o desenquadramento dos Índices de Inadimplemento por duas vezes  consecutivas ou três vezes alternadas dentro de um período de 12 (doze) meses;
 vi. Inobservância, pelo Custodiante, dos deveres e das obrigações previstos neste  Regulamento e nos demais Documentos da Oferta, desde que, notiﬁcado para sanar ou  justiﬁcar o descumprimento, não o faça no prazo de 2 (dois) Dias Úteis, contados do  recebimento da referida notiﬁcação;
 vii. Renúncia do Custodiante, observado o prazo para substituição que estiver previsto na  legislação;
 viii. Inobservância, pela Administradora, dos deveres e das obrigações previstos no  Regulamento e nos demais Documentos da Oferta, conforme o caso, veriﬁcado pelo  Custodiante ou pelos cotistas, desde que, notiﬁcada por estes para sanar ou justiﬁcar o  descumprimento, não o faça no prazo de 15 (quinze) Dias Úteis, contados do recebimento  da referida notiﬁcação;
 ix. Em caso de inobservância, pela Gestora, dos deveres e das obrigações previstos neste  Regulamento e nos demais Documentos da Oferta;
 x. Em caso de inobservância, das Cedentes, conforme deﬁnido no Contrato de Cessão, dos  deveres, declarações, incluindo a obrigação de recomprar o Direito Creditório objeto de  um Evento de Resolução de Cessão, responsabilidades e das obrigações previstos neste  Regulamento e nos demais Documentos da Oferta.
 xi. Caso ocorra a aquisição de Direitos Creditórios representando, pelo menos, 2% (dois  69", "sha256": "dc85b0982f00e4ac6c29d503d98d00ef6bf58635951c800e10fb6158153ebc34", "verification": "primary_passage"}, {"document_id": "1276588", "title": "Regulamento", "url": "https://fnet.bmfbovespa.com.br/fnet/publico/visualizarDocumento?id=1276588", "reference_date": "2026-08-04", "version": "1", "page": 67, "clause": "15.6", "excerpt": "15.6. Para ﬁns do cálculo do valor estimado da Reserva de Liquidez pela Administradora, serão considerados (a) o Limite Superior de Remuneração referente à Data de Pagamento em questão como o valor a ser pago a título de Remuneração; e (b) a Meta de Amortização de Principal referente à Data de Pagamento em questão como valor a ser pago a título de Amortização de Principal.", "sha256": "dc85b0982f00e4ac6c29d503d98d00ef6bf58635951c800e10fb6158153ebc34", "verification": "primary_passage"}]

[{"document_id": "774314", "title": "Regulamento", "url": "https://fnet.bmfbovespa.com.br/fnet/publico/visualizarDocumento?id=774314", "reference_date": "2024-11-05", "version": "1", "page": 50, "clause": "12.1", "excerpt": "12.1. Reserva de Liquidez. A Classe deverá estabelecer uma Reserva de Liquidez, cujo valor mínimo será equivalente a 3 (três) meses de despesas ordinárias da Classe. A Reserva de Liquidez será constituída quando da integralização das Cotas da Classe, e será custeada pelos recursos recebidos pela Classe. Os recursos mantidos na Reserva de Liquidez serão investidos em Ativos Financeiros. A Classe deterá todos os direitos em relação aos Ativos Financeiros e a todos os valores em dinheiro mantidos na Reserva de Liquidez, sendo que os rendimentos dos Ativos Financeiros reverterão em benefício dos Cotistas.", "sha256": "fb7ace31244b9a96a14ae6c7d676296a48d0e741b18832e1ab6518e8955edc0e", "verification": "primary_passage"}, {"document_id": "774314", "title": "Regulamento", "url": "https://fnet.bmfbovespa.com.br/fnet/publico/visualizarDocumento?id=774314", "reference_date": "2024-11-05", "version": "1", "page": 52, "clause": "12.7", "excerpt": "12.7. Ordem de Aplicação de Recursos. Diariamente, a partir do início das atividades da Classe, a Administradora se obriga a utilizar os recursos disponíveis para atender às exigibilidades da Classe, obrigatoriamente, na seguinte ordem de preferência, ressalvado, enquanto em curso um Evento de Avaliação e/ou um Evento de Liquidação, conforme disposto neste Anexo I-A:
(i) pagamento dos Encargos da Classe;
(ii) constituição e/ou recomposição da Reserva de Liquidez;
(iii) pagamento de eventuais parcelas de amortização programada vencidas e não  pagas, que sejam devidas às Cotas Seniores;
(iv) pagamento de resgate de Cotas Seniores aos cotistas dissidentes, nos termos deste  Anexo I-A;
(v) pagamento de amortização ou resgate de Cotas Seniores na respectiva Data de  Amortização, se houver;
(vi) constituição e/ou recomposição da Reserva de Caixa;
(vii) pagamento de eventuais amortizações extraordinárias de Cotas Subordinadas,  observado o disposto no item 4.3.2;
(viii) aquisição pela Classe de Direitos Creditórios, observando-se a Política de  Investimentos; e
(ix) pagamento de resgate de Cotas Subordinadas.", "sha256": "fb7ace31244b9a96a14ae6c7d676296a48d0e741b18832e1ab6518e8955edc0e", "verification": "primary_passage"}, {"document_id": "774314", "title": "Regulamento", "url": "https://fnet.bmfbovespa.com.br/fnet/publico/visualizarDocumento?id=774314", "reference_date": "2024-11-05", "version": "1", "page": 38, "clause": "", "excerpt": "(1) Relação Mínima de Subordinação;
 (2) Alocação Mínima;
 (3) Reserva de Amortização;
 (4) Reserva de Despesas e Encargos;
 (5) Valor das disponibilidades;
 (6) provisões aplicáveis aos Direitos Creditórios Cedidos e Ativos Financeiros;
 (7) valor dos Direitos Creditórios Cedidos;
 (8) Patrimônio Líquido;
 (9) valores agregados das Cotas Seniores e das Cotas Subordinadas em  circulação, segregados por classe e série, conforme aplicável;
 (10) Índice de Resolução de Cessão;
 (11) Rentabilidade das Cotas Sêniores e Subordinadas;", "sha256": "fb7ace31244b9a96a14ae6c7d676296a48d0e741b18832e1ab6518e8955edc0e", "verification": "primary_passage"}]

[{"document_id": "774314", "title": "Regulamento", "url": "https://fnet.bmfbovespa.com.br/fnet/publico/visualizarDocumento?id=774314", "reference_date": "2024-11-05", "version": "1", "page": 38, "clause": "", "excerpt": "(1) Relação Mínima de Subordinação;
 (2) Alocação Mínima;
 (3) Reserva de Amortização;
 (4) Reserva de Despesas e Encargos;
 (5) Valor das disponibilidades;
 (6) provisões aplicáveis aos Direitos Creditórios Cedidos e Ativos Financeiros;
 (7) valor dos Direitos Creditórios Cedidos;
 (8) Patrimônio Líquido;
 (9) valores agregados das Cotas Seniores e das Cotas Subordinadas em  circulação, segregados por classe e série, conforme aplicável;
 (10) Índice de Resolução de Cessão;
 (11) Rentabilidade das Cotas Sêniores e Subordinadas;", "sha256": "fb7ace31244b9a96a14ae6c7d676296a48d0e741b18832e1ab6518e8955edc0e", "verification": "primary_passage"}]

[{"document_id": "1239452", "title": "Regulamento", "url": "https://fnet.bmfbovespa.com.br/fnet/publico/visualizarDocumento?id=1239452", "reference_date": "2026-06-22", "version": "1", "page": 31, "clause": "8.4.3", "excerpt": "8.4.3 O Índice de Subordinação referente à Subclasse de Cotas Subordinadas deverá ser  equivalente a, no mínimo, 15% (quinze por cento).", "sha256": "85ad8b55c767707d78047d050f793d456cab7db09e58ae0d43823f9a6285fb07", "verification": "primary_passage"}, {"document_id": "1239452", "title": "Regulamento", "url": "https://fnet.bmfbovespa.com.br/fnet/publico/visualizarDocumento?id=1239452", "reference_date": "2026-06-22", "version": "1", "page": 44, "clause": "12.4.1", "excerpt": "12.4.1 Sujeito à ordem de alocação dos recursos prevista no CAPÍTULO 13 deste Anexo  Descritivo, e desde que o Período de Alocação ou a Amortização Pro Rata esteja  em curso, se o patrimônio do Fundo permitir, em cada Data de Pagamento será  realizada a Amortização por Excesso de Cobertura das Cotas Subordinadas, em  montante tal que, considerada pro forma a Amortização por Excesso de Cobertura  em questão, o Índice de Subordinação passe a ser de 15% (quinze por cento).", "sha256": "85ad8b55c767707d78047d050f793d456cab7db09e58ae0d43823f9a6285fb07", "verification": "primary_passage"}, {"document_id": "1239452", "title": "Regulamento", "url": "https://fnet.bmfbovespa.com.br/fnet/publico/visualizarDocumento?id=1239452", "reference_date": "2026-06-22", "version": "1", "page": 47, "clause": "13.3.2", "excerpt": "13.3.2 Data de Pagamento; Amortização Pro Rata. Caso a Amortização Pro Rata esteja  em curso, em qualquer data que seja uma Data de Pagamento, os recursos deverão  ser alocados de acordo com a seguinte ordem:
(i) pagamento de Encargos de responsabilidade do Fundo, devidos nos termos deste  Regulamento e da legislação aplicável;
(ii) constituição ou recomposição da Reserva de Despesas e Encargos;
(iii) pagamento da Remuneração referente às Cotas Seniores em circulação;
(iv) pagamento de Amortização de Principal de Cotas Seniores no maior valor que seja  possível de forma que, considerado pro forma o respectivo pagamento e considerada  pro forma a Amortização por Excesso de Cobertura a ser realizada nos termos do  inciso (v) abaixo, o Índice de Subordinação seja equivalente a 15% (quinze por  cento); e
 (v) pagamento da Amortização por Excesso de Cobertura.", "sha256": "85ad8b55c767707d78047d050f793d456cab7db09e58ae0d43823f9a6285fb07", "verification": "primary_passage"}]

[{"document_id": "1239452", "title": "Regulamento", "url": "https://fnet.bmfbovespa.com.br/fnet/publico/visualizarDocumento?id=1239452", "reference_date": "2026-06-22", "version": "1", "page": 47, "clause": "13.3.2", "excerpt": "13.3.2 Data de Pagamento; Amortização Pro Rata. Caso a Amortização Pro Rata esteja  em curso, em qualquer data que seja uma Data de Pagamento, os recursos deverão  ser alocados de acordo com a seguinte ordem:
(i) pagamento de Encargos de responsabilidade do Fundo, devidos nos termos deste  Regulamento e da legislação aplicável;
(ii) constituição ou recomposição da Reserva de Despesas e Encargos;
(iii) pagamento da Remuneração referente às Cotas Seniores em circulação;
(iv) pagamento de Amortização de Principal de Cotas Seniores no maior valor que seja  possível de forma que, considerado pro forma o respectivo pagamento e considerada  pro forma a Amortização por Excesso de Cobertura a ser realizada nos termos do  inciso (v) abaixo, o Índice de Subordinação seja equivalente a 15% (quinze por  cento); e
 (v) pagamento da Amortização por Excesso de Cobertura.", "sha256": "85ad8b55c767707d78047d050f793d456cab7db09e58ae0d43823f9a6285fb07", "verification": "primary_passage"}, {"document_id": "1239452", "title": "Regulamento", "url": "https://fnet.bmfbovespa.com.br/fnet/publico/visualizarDocumento?id=1239452", "reference_date": "2026-06-22", "version": "1", "page": 47, "clause": "13.3.3", "excerpt": "13.3.3 Data de Pagamento; Amortização Sequencial. Caso a Amortização Sequencial  esteja em curso, em qualquer data que seja uma Data de Pagamento, os recursos  deverão ser alocados de acordo com a seguinte ordem:
(i) pagamento de Encargos de responsabilidade do Fundo, devidos nos termos deste  Regulamento e da legislação aplicável;
(ii) constituição ou recomposição da Reserva de Despesas e Encargos;
(iii) pagamento da Remuneração referente às Cotas Seniores em circulação;
(iv) pagamento do restante da Amortização do Principal Sênior com referência às Cotas  Seniores em circulação, considerando, para tanto a amortização de 100% (cem por  cento) da parcela restante do Valor Unitário de Emissão das Cotas Seniores em  circulação; e
(v) somente caso não existam Cotas Seniores em circulação, pagamento da amortização  integral das Cotas Subordinadas.", "sha256": "85ad8b55c767707d78047d050f793d456cab7db09e58ae0d43823f9a6285fb07", "verification": "primary_passage"}, {"document_id": "1239452", "title": "Regulamento", "url": "https://fnet.bmfbovespa.com.br/fnet/publico/visualizarDocumento?id=1239452", "reference_date": "2026-06-22", "version": "1", "page": 34, "clause": "9.2", "excerpt": "9.2 OBRIGAÇÕES ADICIONAIS DA ADMINISTRADORA. Adicionalmente às obrigações previstas  na parte geral do Regulamento, são obrigações da Administradora:
(i) monitorar, nos termos previstos neste Regulamento, a Reserva de Despesas e  Encargos, apurar, em conjunto com a Gestora, nos termos do CAPÍTULO 19 deste  Anexo Descritivo, os valores a serem alocados para pagamento de Encargos de  responsabilidade do Fundo e da Classe A e constituição ou recomposição da  Reserva de Despesas e Encargos;
(ii) acompanhar, nos termos previstos neste Regulamento, os patamares exigidos com  relação aos parâmetros abaixo:", "sha256": "85ad8b55c767707d78047d050f793d456cab7db09e58ae0d43823f9a6285fb07", "verification": "primary_passage"}]

[{"document_id": "918862", "title": "Regulamento", "url": "https://fnet.bmfbovespa.com.br/fnet/publico/visualizarDocumento?id=918862", "reference_date": "2025-06-04", "version": "1", "page": 43, "clause": "9.4", "excerpt": "9.4 Reserva de Liquidez. A partir da 1ª Data de Integralização, o Fundo deverá  estabelecer a Reserva de Liquidez. A Reserva de Liquidez será constituída quando da  integralização das Cotas, e será custeada pelos recursos recebidos pela Classe. Os recursos  mantidos na Reserva de Liquidez serão investidos em Ativos Financeiros. A Classe deterá todos  os direitos em relação aos Ativos Financeiros e a todos os valores em dinheiro mantidos na", "sha256": "1bced29301a3e6641f378baedb4623da94fe1fd07aac1891091b41db86838cbe", "verification": "primary_passage"}, {"document_id": "918862", "title": "Regulamento", "url": "https://fnet.bmfbovespa.com.br/fnet/publico/visualizarDocumento?id=918862", "reference_date": "2025-06-04", "version": "1", "page": 46, "clause": "10.4.2", "excerpt": "10.4.2 Ordem de alocação dos recursos intra-mês para datas que não sejam Datas de  Pagamento, caso a Amortização Pro Rata esteja em curso:
(i) pagamento das despesas e encargos da Classe;
(ii) constituição e/ou recomposição da Reserva de Liquidez;", "sha256": "1bced29301a3e6641f378baedb4623da94fe1fd07aac1891091b41db86838cbe", "verification": "primary_passage"}, {"document_id": "918862", "title": "Regulamento", "url": "https://fnet.bmfbovespa.com.br/fnet/publico/visualizarDocumento?id=918862", "reference_date": "2025-06-04", "version": "1", "page": 47, "clause": "10.4.3", "excerpt": "10.4.3 Ordem de alocação dos recursos intra-mês para datas que não sejam Datas de  Pagamento, caso a Amortização Sequencial esteja em curso:
(i) pagamento das despesas e encargos da Classe;
(ii) constituição e/ou recomposição da Reserva de Liquidez; e
(iii) constituição e/ou recomposição da Reserva de Caixa, Amortização e resgate das Cotas,  conforme aplicável.", "sha256": "1bced29301a3e6641f378baedb4623da94fe1fd07aac1891091b41db86838cbe", "verification": "primary_passage"}]

[{"document_id": "1343190", "title": "Regulamento", "url": "https://fnet.bmfbovespa.com.br/fnet/publico/visualizarDocumento?id=1343190", "reference_date": "2026-10-06", "version": "1", "page": 33, "clause": "9.1", "excerpt": "9.1. Além das obrigações previstas neste Anexo I-A e, sem prejuízo das demais disposições  da regulamentação aplicável, incluem-se, entre as obrigações da Administradora:
(i) monitorar a Reserva de Caixa e a Reserva de Amortização ou Resgate;
(ii) entregar ao Cotista, gratuitamente, exemplar deste Anexo I-A, bem como  cientificá-lo de que a divulgação de informações sobre a Classe é realizada por meio do  site da Administradora (www.oliveiratrust.com.br) e disponibilização no Fundos.Net;
(iii) além de manter disponíveis em sua sede e agências e nas instituições que  coloquem Cotas, divulgar anualmente na forma descrita no inciso (ii) acima o valor do  Patrimônio Líquido da Classe, o valor das Cotas da Classe e as rentabilidades  acumuladas no mês e no ano civil a que se referirem;
(iv) fornecer anualmente aos Cotistas, documento contendo informações sobre os  rendimentos auferidos no ano civil e, com base nos dados relativos ao último dia do  mês de dezembro, sobre o número de Cotas de sua propriedade e respectivo valor;
(v) sem prejuízo da observância dos procedimentos relativos às demonstrações  financeiras previstas neste Regulamento e nas normas cabíveis, manter,  separadamente, registros analíticos com informações completas sobre toda e qualquer  modalidade de negociação realizada pela Classe, inclusive entre a Administradora e a  Classe;
(vi) disponibilizar e manter atualizados em sua página eletrônica na rede mundial  de computadores as regras e procedimentos exigidos pela regulação aplicável e  previstos neste Anexo I-A;
(vii) divulgar, em sua página eletrônica na rede mundial de computadores,  quaisquer informações relativas à Classe divulgadas para Cotistas ou terceiros, exceto  quando se tratar de informações divulgadas a (i) prestadores de serviços da Classe,  desde que tais informações sejam necessárias à execução de suas atividades, e (ii)  órgãos reguladores e autorreguladores, quando tais informações visem atender  solicitações legais, regulamentares ou estatutárias;
(viii) calcular e divulgar mensalmente até o 5º (quinto) Dia Útil de cada mês  calendário e manter em seu website informações atualizadas em relação a todos os  índices a serem utilizados na avaliação do desempenho da Classe e/ou dos Direitos  Creditórios que compõem a carteira da Classe, inclusive, sem limitação, o Índice de", "sha256": "7a7233d733e9a1836d62b0f69e10207850853c92d39866e3d34e4a46ccb6f975", "verification": "primary_passage"}, {"document_id": "1343190", "title": "Regulamento", "url": "https://fnet.bmfbovespa.com.br/fnet/publico/visualizarDocumento?id=1343190", "reference_date": "2026-10-06", "version": "1", "page": 41, "clause": "", "excerpt": "(ii) constituição e/ou recomposição da Reserva de Caixa e da Reserva de  Amortização ou Resgate, quando aplicável;", "sha256": "7a7233d733e9a1836d62b0f69e10207850853c92d39866e3d34e4a46ccb6f975", "verification": "primary_passage"}, {"document_id": "1343190", "title": "Regulamento", "url": "https://fnet.bmfbovespa.com.br/fnet/publico/visualizarDocumento?id=1343190", "reference_date": "2026-10-06", "version": "1", "page": 45, "clause": "", "excerpt": "(vii) não constituição e/ou manutenção da Reserva de Amortização ou Resgate ou  da Reserva de Caixa, nos termos previstos neste Regulamento, que não seja curada no  prazo de 10 (dez) Dias Úteis;", "sha256": "7a7233d733e9a1836d62b0f69e10207850853c92d39866e3d34e4a46ccb6f975", "verification": "primary_passage"}]

[{"document_id": "909547", "title": "Regulamento", "url": "https://fnet.bmfbovespa.com.br/fnet/publico/visualizarDocumento?id=909547", "reference_date": "2025-05-19", "version": "1", "page": 87, "clause": "7.4", "excerpt": "7.4 Aporte Adicional para Cobrança dos Direitos Creditórios Adquiridos  Inadimplidos. Todos os custos e despesas que venham a ser incorridos pela Classe  Única para salvaguarda de seus direitos e prerrogativas e/ou com a cobrança judicial de  Direitos Creditórios Adquiridos Inadimplidos, além do valor total inicial aportado pelos  Cotistas na Classe Única no âmbito da integralização das Cotas e os recursos da  Reserva de Liquidez, serão de inteira responsabilidade dos Cotistas, por meio de novo  aporte de recursos na Classe (mediante a subscrição de novas Cotas), conforme  87", "sha256": "51826432a3c2344c1d349efc06ffeae1d8d9f45a3ff78e362253c98cd266549c", "verification": "primary_passage"}, {"document_id": "909547", "title": "Regulamento", "url": "https://fnet.bmfbovespa.com.br/fnet/publico/visualizarDocumento?id=909547", "reference_date": "2025-05-19", "version": "1", "page": 97, "clause": "8.2.1", "excerpt": "8.2.1 Ordem de Prioridade na Amortização e Remuneração das Cotas. Em  cada Data de Amortização e em cada Data de Pagamento de Remuneração, a  amortização das Cotas e a distribuição dos rendimentos do Fundo deverão observar a  seguinte ordem de prioridade, conforme ordem de alocação de recursos prevista no  Artigo 10.7abaixo:
(i) primeiro, na medida necessária para o pagamento dos Encargos do  Fundo, os valores recebidos na Conta Movimento da Classe Única serão retidos e pagos  aos respectivos beneficiários na(s) respectiva(s) data(s) de vencimento;
(ii) segundo, na medida necessária para a manutenção da Reserva de  Liquidez, os valores recebidos na Conta Movimento da Classe Única ficarão retidos na  mesma, em valor equivalente à Reserva de Liquidez, sendo certo que a disponibilidade  ficará aplicada em Ativos Financeiros;
(iii) terceiro, todos os valores remanescentes na Conta Movimento da Classe  Única serão distribuídos aos Cotistas Seniores na extensão necessária para  cumprimento dos pagamentos constantes do cronograma de remuneração e  amortização de principal disposto no Apêndice A e no(s) Adendo(s) ao Apêndice A, até  o Índice Referencial das Cotas Seniores, acrescido do Spread Adicional, caso aplicável;
(iv) quarto, todos os valores remanescentes na Conta Movimento da Classe  Única serão distribuídos aos Cotistas Subordinados Mezanino na extensão necessária  para cumprimento dos pagamentos constantes do cronograma de remuneração e  amortização de principal disposto no Apêndice B e no(s) Adendo(s) ao Apêndice B, até  o Índice Referencial das Cotas Subordinadas Mezanino;
(v) quinto, na medida necessária para a manutenção da Reserva de Caixa,  os valores recebidos na Conta Movimento da Classe Única ficarão aplicados em Ativos  Financeiros; e
(vi) sexto, caso haja uma solicitação neste sentido dos Cotistas  Subordinados Juniores, todos os valores remanescentes na Conta Movimentação da  Classe Única serão distribuídos aos Cotistas Subordinados Juniores, conforme o  Apêndice C, até o limite em que, considerada pro forma a amortização do Cotista  Subordinado Júnior, o Índice de Subordinação continue a ser atendido, conforme  previsto nos Artigos 8.2.2 e 8.2.3 abaixo.", "sha256": "51826432a3c2344c1d349efc06ffeae1d8d9f45a3ff78e362253c98cd266549c", "verification": "primary_passage"}, {"document_id": "909547", "title": "Regulamento", "url": "https://fnet.bmfbovespa.com.br/fnet/publico/visualizarDocumento?id=909547", "reference_date": "2025-05-19", "version": "1", "page": 103, "clause": "10.1", "excerpt": "10.1 Reserva de Liquidez. A Classe Única deverá estabelecer uma Reserva  de Liquidez, cujo valor mínimo será equivalente a 3 (três) meses de despesas ordinárias  da Classe Única, assim entendidas como as despesas de manutenção de contratação  dos prestadores de serviços da Classe Única, na proporção devida pela Classe Única.", "sha256": "51826432a3c2344c1d349efc06ffeae1d8d9f45a3ff78e362253c98cd266549c", "verification": "primary_passage"}]

[{"document_id": "1002580", "title": "Regulamento", "url": "https://fnet.bmfbovespa.com.br/fnet/publico/visualizarDocumento?id=1002580", "reference_date": "2025-09-29", "version": "1", "page": 39, "clause": "9.2", "excerpt": "9.2 OBRIGAÇÕES ADICIONAIS DA ADMINISTRADORA. Adicionalmente às obrigações previstas na  parte geral do Regulamento, são obrigações da Administradora:
(i) monitorar, nos termos previstos neste Regulamento, a Reserva de Despesas e  Encargos e a Reserva de Liquidez;
(ii) acompanhar, nos termos previstos neste Regulamento, os patamares exigidos  para a composição do Relatório de Monitoramento;
(iii) monitorar a ocorrência de quaisquer Eventos de Avaliação e/ou Eventos de  Liquidação;
(iv) verificar a ocorrência de Eventos de Desalavancagem e Eventos de  Realavancagem, conforme monitorados pela Gestora em cada Data de  Verificação; e
(v) divulgar aos Cotistas cada Relatório de Monitoramento na mesma data de seu  recebimento.", "sha256": "3f5f01a936ccd77eb1497e559a28ca9e02cff9a5d45a7ada0933730f0afb0320", "verification": "primary_passage"}, {"document_id": "1002580", "title": "Regulamento", "url": "https://fnet.bmfbovespa.com.br/fnet/publico/visualizarDocumento?id=1002580", "reference_date": "2025-09-29", "version": "1", "page": 71, "clause": "19.2", "excerpt": "19.2 Adicionalmente, a Administradora deverá manter Reserva de Liquidez, por conta e  ordem do Fundo, desde a 1ª Data de Integralização de Cotas, a partir de 30 (trinta)  dias antes da Data de Pagamento, de acordo com o disposto nos itens abaixo:", "sha256": "3f5f01a936ccd77eb1497e559a28ca9e02cff9a5d45a7ada0933730f0afb0320", "verification": "primary_passage"}, {"document_id": "1002580", "title": "Regulamento", "url": "https://fnet.bmfbovespa.com.br/fnet/publico/visualizarDocumento?id=1002580", "reference_date": "2025-09-29", "version": "1", "page": 71, "clause": "19.2.1", "excerpt": "19.2.1 Observada a ordem de alocação de recursos estabelecida no CAPÍTULO  13, a cada Dia Útil a Reserva de Liquidez será constituída com os recursos  decorrentes do pagamento dos Direitos Creditórios Adquiridos e dos Ativos  Financeiros integrantes da carteira da Classe retidos pela Gestora até o  montante da Remuneração das Cotas Seniores previsto para a próxima Data de  Pagamento.", "sha256": "3f5f01a936ccd77eb1497e559a28ca9e02cff9a5d45a7ada0933730f0afb0320", "verification": "primary_passage"}]

[{"document_id": "1002580", "title": "Regulamento", "url": "https://fnet.bmfbovespa.com.br/fnet/publico/visualizarDocumento?id=1002580", "reference_date": "2025-09-29", "version": "1", "page": 39, "clause": "9.2", "excerpt": "9.2 OBRIGAÇÕES ADICIONAIS DA ADMINISTRADORA. Adicionalmente às obrigações previstas na  parte geral do Regulamento, são obrigações da Administradora:
(i) monitorar, nos termos previstos neste Regulamento, a Reserva de Despesas e  Encargos e a Reserva de Liquidez;
(ii) acompanhar, nos termos previstos neste Regulamento, os patamares exigidos  para a composição do Relatório de Monitoramento;
(iii) monitorar a ocorrência de quaisquer Eventos de Avaliação e/ou Eventos de  Liquidação;
(iv) verificar a ocorrência de Eventos de Desalavancagem e Eventos de  Realavancagem, conforme monitorados pela Gestora em cada Data de  Verificação; e
(v) divulgar aos Cotistas cada Relatório de Monitoramento na mesma data de seu  recebimento.", "sha256": "3f5f01a936ccd77eb1497e559a28ca9e02cff9a5d45a7ada0933730f0afb0320", "verification": "primary_passage"}, {"document_id": "1002580", "title": "Regulamento", "url": "https://fnet.bmfbovespa.com.br/fnet/publico/visualizarDocumento?id=1002580", "reference_date": "2025-09-29", "version": "1", "page": 53, "clause": "13.3", "excerpt": "13.3 Após o Período de Investimento e Período de Carência; Amortização Pro Rata. Caso a  Amortização Pro Rata esteja em curso, em qualquer data que não seja durante o Período  de Investimento e o Período de Carência, os recursos deverão ser alocados de acordo  com a seguinte ordem:
(i) pagamento dos encargos e despesas correntes da Classe, incluindo todos os  saldos e as despesas decorrentes de contratos de derivativos celebrados pela  Classe;
(ii) constituição e manutenção da Reserva de Despesas e Encargos;", "sha256": "3f5f01a936ccd77eb1497e559a28ca9e02cff9a5d45a7ada0933730f0afb0320", "verification": "primary_passage"}, {"document_id": "1002580", "title": "Regulamento", "url": "https://fnet.bmfbovespa.com.br/fnet/publico/visualizarDocumento?id=1002580", "reference_date": "2025-09-29", "version": "1", "page": 71, "clause": "19.1", "excerpt": "19.1 Observada a ordem de alocação de recursos prevista no CAPÍTULO 13 deste Anexo  Descritivo, a Administradora deverá manter Reserva de Despesas e Encargos da Classe,  por conta e ordem da Classe, desde a 1ª Data de Integralização de Cotas até a  liquidação da Classe, equivalente ao valor estimado necessário para o pagamento de  despesas ordinárias identificadas como Encargos do Fundo, nos termos do CAPÍTULO  16 deste Regulamento, incluindo-se a Taxa de Administração, referentes aos 3 (três)  meses subsequentes.", "sha256": "3f5f01a936ccd77eb1497e559a28ca9e02cff9a5d45a7ada0933730f0afb0320", "verification": "primary_passage"}]

[{"document_id": "1013021", "title": "Regulamento", "url": "https://fnet.bmfbovespa.com.br/fnet/publico/visualizarDocumento?id=1013021", "reference_date": "2024-11-14", "version": "1", "page": 31, "clause": "4.2", "excerpt": "4.2. A Classe Única deverá ter alocado, no mínimo, 67% (sessenta e sete por cento), e, no máximo, 100% (cem por cento) de seu patrimônio em Direitos Creditórios, observada, ainda, a alocação de recursos para a Reserva de Liquidez e Reserva de Caixa.", "sha256": "56d3035e042e3c6dcb827f17d8f320a2e78d46d8f8acaa6ab5e26ac201daeb10", "verification": "primary_passage"}, {"document_id": "1013021", "title": "Regulamento", "url": "https://fnet.bmfbovespa.com.br/fnet/publico/visualizarDocumento?id=1013021", "reference_date": "2024-11-14", "version": "1", "page": 75, "clause": "21.3", "excerpt": "21.3. No curso ordinário do Programa de Securitização e observada a ordem de aplicação de recursos definida neste Capítulo e a política de investimento constante do Capítulo IV, a Administradora deverá segregar na contabilidade da Classe Única e manter aplicada nas modalidades de investimento referidas nos subitens “a” a “c” do item (4.5): (a) parcela de seu Patrimônio Líquido equivalente ao montante estimado dos encargos de responsabilidade da Classe Única a serem incorridos nos 3 (três) meses calendários subsequentes à realização do respectivo provisionamento (“Reserva de Caixa”), e (b) uma reserva de liquidez equivalente a 3% (três por cento) do valor presente dos Direitos Creditórios integrantes da carteira da Classe Única (“Reserva de Liquidez”).", "sha256": "56d3035e042e3c6dcb827f17d8f320a2e78d46d8f8acaa6ab5e26ac201daeb10", "verification": "primary_passage"}, {"document_id": "1013021", "title": "Regulamento", "url": "https://fnet.bmfbovespa.com.br/fnet/publico/visualizarDocumento?id=1013021", "reference_date": "2024-11-14", "version": "1", "page": 29, "clause": "", "excerpt": "108) “Programa de Securitização”: mecanismos e procedimentos definidos nos Documentos da Securitização por meio dos quais os Cedentes cedem Direitos Creditórios Elegíveis a Classe Única, captando recursos para suas atividades;
109) “Razão de Garantia”: para fins do inciso XV do artigo 2º do Anexo Descritivo II da Resolução CVM 175, é a fração cujo numerador é equivalente ao somatório do valor atualizado das Cotas Seniores, deduzido o valor dos Outros Ativos, e o denominador é o valor do Patrimônio Líquido, deduzido o valor dos Outros Ativos, apurada diariamente pela Gestora (exemplo: se Razão de Garantia for 0,95, então Razão de Garantia = 95%);
110) “Regulamento”: o regulamento do Fundo;
111) “Reserva de Caixa”: tem o significado que lhe é atribuído no item (21.3.) do Capítulo XXI;
112) “Reserva de Liquidez”: tem o significado que lhe é atribuído no item (21.3.) do Capítulo XXI;
113) “Resolução CMN nº 2.907”: Resolução nº 2.907, de 29 de novembro de 2001, do CMN;
114) “Resolução CVM 30”: significa a Resolução CVM nº 30, de 11 de maio de 2021, conforme alterada.
115) “Resolução CVM 160”: significa a Resolução CVM nº 160, de 13 de julho de 2022, conforme alterada.
116) “Resolução CVM 175” significa a Resolução CVM nº 175, de 23 de dezembro de 2022, conforme alterada.
117) “Saque”: operação de crédito através da emissão de uma Cédula de Crédito Bancário, com a cobrança de Encargos, contratada pelo Titular, por meio da utilização do Cartão;
118) “SELIC”: Sistema Especial de Liquidação de Custódia;
119) “Subclasse”: significam as subclasses de Cotas da Classe Única do Fundo, que são divididas em Cotas Seniores, Cotas Mezanino I, Cotas Mezanino II e Cotas Subordinadas.
120) “SISBACEN”: Sistema de Informações do Bacen;
121) “SpreadSen”: tem o significado que lhe é atribuído no item (16.1) do Capítulo XVI;
122) “Supplier”: Supplier Administradora de Cartões de Crédito S.A., sociedade anônima com sede na Cidade de São Paulo, Estado de São Paulo, na Avenida Paulista, nº 1728, 12º, 13º (parte) e 14º (parte) andares, inscrita no CNPJ sob o nº 06.951.711/0001-28;
123) “Taxa de Administração”: tem o significado que lhe é atribuído no item (9.1) do Capítulo IX;
124) “Taxa de Gestão”: tem o significado que lhe é atribuído no item (9.2) do Capítulo IX;
125) “Taxa DI”: tem o significado que lhe é atribuído no subitem “b” do item (16.1) do Capítulo XVI;
126) “Taxa Mínima de Desconto”: taxa apurada de acordo com a seguinte fórmula:", "sha256": "56d3035e042e3c6dcb827f17d8f320a2e78d46d8f8acaa6ab5e26ac201daeb10", "verification": "primary_passage"}]

[{"document_id": "852325", "title": "Regulamento", "url": "https://fnet.bmfbovespa.com.br/fnet/publico/visualizarDocumento?id=852325", "reference_date": "2025-02-25", "version": "1", "page": 18, "clause": "", "excerpt": "“Índice de Subordinação” Significa o resultado da razão entre o valor total das Cotas  Subordinadas e o Patrimônio Líquido, que deverá ser apurada pelo  Gestor e deverá corresponder a, no mínimo, 33,33% (trinta e três  inteiros e trinta e três centésimos por cento).", "sha256": "61431b51f061ec6a54c40b0c59ae663102fc8d847df839cf44cc100685087743", "verification": "primary_passage"}, {"document_id": "852325", "title": "Regulamento", "url": "https://fnet.bmfbovespa.com.br/fnet/publico/visualizarDocumento?id=852325", "reference_date": "2025-02-25", "version": "1", "page": 34, "clause": "8.2", "excerpt": "8.2. Incluem-se entre as obrigações do Administrador aquelas dispostas nos artigos 82 e  83, conforme aplicável, e 104 da parte geral da Resolução CVM 175/22 e no artigo 30 do Anexo  Normativo II da Resolução CVM 175/22. Sem prejuízo de seus outros deveres legais e  regulamentares, são obrigações do Administrador:
(i) contratar terceiros devidamente habilitados e autorizados, ou executar por conta própria, os  serviços de tesouraria, controle e processamento dos ativos;
(ii) contratar auditoria independente, nos termos do artigo 69 da Resolução CVM 175;
(iii) diligenciar para que sejam mantidos, às suas expensas, atualizados e em perfeita ordem: (a)  o registro de Cotistas; (b) o livro de atas das assembleias gerais; (c) o livro ou lista de  presença de cotistas; (d) os pareceres do auditor independente; e (e) os registros contábeis  referentes às operações e ao Patrimônio Líquido do Fundo;
(iv) solicitar, se for o caso, a admissão à negociação das cotas de classe fechada em mercado  organizado;
(v) observar as disposições do Código ANBIMA e das Regras e Procedimentos do Código  ANBIMA;
(vi) acompanhar o enquadramento do Índice de Subordinação definido para no Anexo  Descritivo, conforme calculado e monitorado pelo Gestor;", "sha256": "61431b51f061ec6a54c40b0c59ae663102fc8d847df839cf44cc100685087743", "verification": "primary_passage"}, {"document_id": "852325", "title": "Regulamento", "url": "https://fnet.bmfbovespa.com.br/fnet/publico/visualizarDocumento?id=852325", "reference_date": "2025-02-25", "version": "1", "page": 18, "clause": "", "excerpt": "“Índices de Monitoramento” São os índices verificados e calculados pelo Gestor, quando  mencionados em conjunto: (i) Alocação Mínima de Investimento;
 e (ii) Índice de Subordinação.", "sha256": "61431b51f061ec6a54c40b0c59ae663102fc8d847df839cf44cc100685087743", "verification": "primary_passage"}]

[{"document_id": "826212", "title": "Instrumento Particular de Alteração do Regulamento", "url": "https://fnet.bmfbovespa.com.br/fnet/publico/visualizarDocumento?id=826212", "reference_date": "2025-01-28", "version": "1", "page": 79, "clause": "21.1", "excerpt": "21.1. Observada a ordem de alocação de recursos prevista no Capítulo 15 deste Regulamento, a Gestora  deverá manter a Reserva de Despesas e Encargos desde a Data de Início do Fundo até a sua liquidação,  equivalente ao valor estimado necessário para o pagamento de despesas ordinárias, identificadas como  encargos do Fundo, nos termos do item 20.1 acima, incluindo a Taxa de Administração e a Taxa de Gestão,  referente aos 3 (três) meses subsequentes. Os recursos utilizados para composição da Reserva de Despesas  e Encargos serão obrigatoriamente mantidos em Disponibilidades.", "sha256": "a1ad336efcfa37b2ff6f2fac86405ac61a2c9f45cc5bf23bc244593ea5f99089", "verification": "primary_passage"}, {"document_id": "826212", "title": "Instrumento Particular de Alteração do Regulamento", "url": "https://fnet.bmfbovespa.com.br/fnet/publico/visualizarDocumento?id=826212", "reference_date": "2025-01-28", "version": "1", "page": 80, "clause": "21.3", "excerpt": "21.3. Os procedimentos descritos neste Capítulo 21 não constituem promessa ou garantia, por parte da  Gestora, de que haverá recursos suficientes para a constituição da Reserva de Despesas e Encargos ou da  Reserva de Remuneração, representando apenas um objetivo a ser perseguido.", "sha256": "a1ad336efcfa37b2ff6f2fac86405ac61a2c9f45cc5bf23bc244593ea5f99089", "verification": "primary_passage"}, {"document_id": "826212", "title": "Instrumento Particular de Alteração do Regulamento", "url": "https://fnet.bmfbovespa.com.br/fnet/publico/visualizarDocumento?id=826212", "reference_date": "2025-01-28", "version": "1", "page": 13, "clause": "", "excerpt": "(5) Índices de Concentração;
 (6) Índice de Pagamentos Incorretos;
 (7) Índice de Erros;
 (8) Alocações Mínimas;
 (9) Reserva de Remuneração;
 (10) Reserva de Despesas e Encargos;
 (11) Reserva de Ajuste de Preço;
 (12) Disponibilidades;
 (13) Valor das Disponibilidades; e  (14) provisões aplicáveis aos Ativos Financeiros mantidos em Disponibilidades;", "sha256": "a1ad336efcfa37b2ff6f2fac86405ac61a2c9f45cc5bf23bc244593ea5f99089", "verification": "primary_passage"}]

[{"document_id": "741138", "title": "Instrumento Particular de Alteração do Regulamento", "url": "https://fnet.bmfbovespa.com.br/fnet/publico/visualizarDocumento?id=741138", "reference_date": "2024-09-17", "version": "1", "page": 75, "clause": "", "excerpt": "contrato de venda da respectiva commodity, assinada pelo respectivo emitente produtor rural, pela Cooperativa, pela trading adquirente do respectivo produto e pelo Fundo, em benefício da Classe; (ii) cessão fiduciária de CPR-F, emitidas ou a serem emitidas por produtores rurais que tenham relações comerciais com as Cooperativas, com garantia de penhor agrícola cedularmente constituído, observado o Limite da Capacidade Produtiva; (iii) cessão fiduciária de recebíveis sob duplicatas e duplicatas rurais, a serem emitidas pelas Cooperativas em favor de produtores rurais que sejam cooperados de tais Cooperativas, ou notas promissórias rurais ou notas promissórias emitidas por produtores rurais que sejam cooperados de tais Cooperativas, observado que as duplicatas, duplicatas rurais e notas promissórias deverão
(a) ter concentração de riscos no máximo 20% (vinte por cento) por Grupo Econômico do valor devido sob as duplicatas, duplicatas rurais, notas promissórias e notas promissórias rurais cedidas em garantia (“Limite de Concentração”), e (b) no caso de duplicatas e duplicatas rurais, conter o aceite de seu devedor, ou, quando houver nota fiscal, esta deverá estar acompanhada do respectivo canhoto de entrega, sendo que o devedor será notificado por qualquer meio admitido em direito sobre a garantia constituída sobre referidas duplicatas, duplicatas rurais, notas promissórias rurais e notas promissórias; (iv) alienação fiduciária de bem imóvel, formalizada por meio de instrumento apartado à respectiva CPR-F; (v) hipoteca de imóvel, formalizada por meio de instrumento apartado à respectiva CPR-F; (vi) cessão fiduciária de demais direitos creditórios a que a Cooperativa faça jus ou ativos de sua propriedade que sejam ou venham a ser aprovados pela Classe; e (vii) aval, observado que tais garantias deverão ser apresentadas pelas Cooperativas em até 120 (cento e vinte) dias antes do vencimento das respectivas CPR-F.", "sha256": "e7797e0b4369cbbfb6dd2b76fae35ae22faf7a9999e243619110208d4074fed1", "verification": "primary_passage"}, {"document_id": "741138", "title": "Instrumento Particular de Alteração do Regulamento", "url": "https://fnet.bmfbovespa.com.br/fnet/publico/visualizarDocumento?id=741138", "reference_date": "2024-09-17", "version": "1", "page": 102, "clause": "", "excerpt": "(xxi) considerando-se pro forma a aquisição pretendida, o valor de face dos Direitos  Creditórios devidos de um mesmo Devedor (considerado em conjunto com as  demais integrantes do seu Grupo Econômico), devem estar limitados a 5% (cinco  por cento) do Patrimônio Líquido da Classe; e", "sha256": "e7797e0b4369cbbfb6dd2b76fae35ae22faf7a9999e243619110208d4074fed1", "verification": "primary_passage"}, {"document_id": "741138", "title": "Instrumento Particular de Alteração do Regulamento", "url": "https://fnet.bmfbovespa.com.br/fnet/publico/visualizarDocumento?id=741138", "reference_date": "2024-09-17", "version": "1", "page": 76, "clause": "", "excerpt": "“Garantias Significam as garantias que deverão ou poderão, conforme Distribuidores” aplicável, ser constituídas pelos Distribuidores em benefício  da Classe, quais sejam: (i) cessão fiduciária de cédulas de  produto rural físicas, devidamente formalizadas, com  garantia de penhor agrícola de até 2º grau cedularmente  constituído, observado que o montante empenhado não  poderá ultrapassar Limite da Capacidade Produtiva. A  produtividade da área será calculada de acordo com as  informações disponibilizadas pela Companhia Nacional de  Abastecimento – CONAB. Cada cédula de produto rural  física deverá ser acompanhada por cessão para a Classe  dos recebíveis do contrato de venda da respectiva  commodity, assinada pelo respectivo emitente produtor  rural, pelo Distribuidor, pela trading adquirente do  respectivo produto e pelo Fundo, em benefício da Classe;
 (ii) cessão fiduciária de CPR-F, emitidas ou a serem  emitidas por produtores rurais que tenham relações  comerciais com os Distribuidores, com garantia de penhor  agrícola cedularmente constituído, observado o Limite da  Capacidade Produtiva e o Limite de Concentração; (iii)  cessão fiduciária de recebíveis sob duplicatas e duplicatas  rurais, a serem emitidas pelos Distribuidores em favor de  produtores rurais que sejam seus respectivos clientes, ou  notas promissórias rurais ou notas promissórias emitidas  por produtores rurais que sejam clientes de tais  Distribuidores, observado que (a) as duplicatas, duplicatas  rurais e notas promissórias deverão observar o Limite de  Concentração, e (b) no caso de duplicatas e duplicatas  rurais, conter o aceite de seu devedor, ou, quando houver  nota fiscal, esta deverá estar acompanhada do respectivo  canhoto de entrega, sendo que o devedor será notificado  por qualquer meio admitido em direito sobre a garantia  constituída sobre referidas duplicatas, duplicatas rurais,  notas promissórias rurais e notas promissórias; (iv)  alienação fiduciária de bem imóvel; (v) hipoteca de imóvel;
 (vi) cessão fiduciária de demais direitos creditórios a que  o Distribuidor faça jus ou ativos de sua propriedade que  sejam ou venham a ser aprovados pela Classe; e (vii) aval,", "sha256": "e7797e0b4369cbbfb6dd2b76fae35ae22faf7a9999e243619110208d4074fed1", "verification": "primary_passage"}]

[{"document_id": "741138", "title": "Instrumento Particular de Alteração do Regulamento", "url": "https://fnet.bmfbovespa.com.br/fnet/publico/visualizarDocumento?id=741138", "reference_date": "2024-09-17", "version": "1", "page": 98, "clause": "", "excerpt": "(iv) considerando-se pro forma a aquisição pretendida, (a) os Direitos Creditórios  com vencimento nos dois meses anteriores à próxima Data de Pagamento,  deverão representar, no mínimo, 35% (trinta e cinco por cento) do Patrimônio  Líquido da Classe e/ou (b) Reserva de Liquidez suficiente para fazer frente às  Despesas do Fundo e aos pagamentos referentes à próxima Data de Pagamento.", "sha256": "e7797e0b4369cbbfb6dd2b76fae35ae22faf7a9999e243619110208d4074fed1", "verification": "primary_passage"}, {"document_id": "741138", "title": "Instrumento Particular de Alteração do Regulamento", "url": "https://fnet.bmfbovespa.com.br/fnet/publico/visualizarDocumento?id=741138", "reference_date": "2024-09-17", "version": "1", "page": 129, "clause": "", "excerpt": "11. Reserva de Liquidez. O Gestor estabelecerá, nos Dias Úteis que sejam Datas de Recomposição da Reserva de Liquidez, uma Reserva de Liquidez com o intuito de cobrir todas as despesas e os pagamentos de Amortização de Principal e de Remuneração das Cotas emitidas pela Classe esperados durante o respectivo Período de Liquidez. Observado o disposto abaixo, o montante acumulado na Reserva de Liquidez deverá necessariamente corresponder à soma entre os seguintes valores estimados a serem incorridos durante o Período de Liquidez: (i) Despesas da Classe; e
(ii) Meta de Amortização (englobando a Meta de Amortização de Principal e o Limite Superior de Remuneração) e eventual Prêmio de Excesso de Spread. Não obstante o disposto acima, o montante da Reserva de Liquidez no primeiro Dia Útil de qualquer Período de Liquidez sempre deverá corresponder a, no mínimo, 1% (um por cento) do Patrimônio Líquido.", "sha256": "e7797e0b4369cbbfb6dd2b76fae35ae22faf7a9999e243619110208d4074fed1", "verification": "primary_passage"}, {"document_id": "741138", "title": "Instrumento Particular de Alteração do Regulamento", "url": "https://fnet.bmfbovespa.com.br/fnet/publico/visualizarDocumento?id=741138", "reference_date": "2024-09-17", "version": "1", "page": 134, "clause": "", "excerpt": "12. Eventos de Avaliação. Qualquer dos seguintes eventos será considerado um Evento de Avaliação:
(i) violação das declarações, obrigações e garantias do Originador no âmbito dos  Termos e Condições Gerais de Cessão e Aquisição, no Contrato de Cessão  Sumitomo ou demais documentos integrantes da Classe e que não sejam sanadas  pelo Originador ou Cedente em até 5 (cinco) Dias Úteis a contar do recebimento,  pelo Originador e/ou Cedente, conforme o caso, de notificação enviada pelo  Administrador nesse sentido;
(ii) caso ocorra a aquisição de Direitos Creditórios que não sejam sanadas pelo  Originador, Custodiante, Administrador, Gestor ou Cedente em até 5 (cinco) Dias  Úteis a contar do recebimento da notificação, representando, pelo menos, 2%  (dois por cento) do Patrimônio Líquido, em desconformidade com as Condições  de Cessão e Critérios de Elegibilidade estabelecidos neste Anexo Descritivo;
(iii) a não recomposição da Reserva de Liquidez, observadas as disposições do  Capítulo Décimo e item 11 acima, que não seja sanada em até 5 (cinco) Dias Úteis  contados da caracterização do referido evento;
(iv) se houver violação a quaisquer dos Índices de Monitoramento descritos no item", "sha256": "e7797e0b4369cbbfb6dd2b76fae35ae22faf7a9999e243619110208d4074fed1", "verification": "primary_passage"}]

[{"document_id": "801978", "title": "Regulamento", "url": "https://fnet.bmfbovespa.com.br/fnet/publico/visualizarDocumento?id=801978", "reference_date": "2024-12-12", "version": "1", "page": 33, "clause": "5.4", "excerpt": "5.4. Limite de Concentração por Devedor. A aplicação de recursos em Direitos Creditórios e outros ativos de responsabilidade ou coobrigação de um mesmo Devedor está limitada a 20% (vinte por cento) do Patrimônio Líquido da Classe Única.", "sha256": "2e89a71cde9ceccd2584e6089c2a4d15712f2efda1a7b8ffa04338d29a91896b", "verification": "primary_passage"}, {"document_id": "801978", "title": "Regulamento", "url": "https://fnet.bmfbovespa.com.br/fnet/publico/visualizarDocumento?id=801978", "reference_date": "2024-12-12", "version": "1", "page": 40, "clause": "", "excerpt": "prazo máximo de vencimento de até 240 Administradora e do  (duzentos e quarenta) dias com base na Data Agente de  de Aquisição, observado o prazo de Formalização  desinvestimento das Cotas Seniores; e (b)  25% (vinte e cinco por cento) do Patrimônio  Líquido da Classe Única poderá extrapolar o  prazo do item “(a)” acima, contudo não  deverá ser superior a 365 (trezentos e  sessenta e cinco) dias com base na Data de  Aquisição;
 deverão ter prazo de vencimento de, no  Gestora, com  mínimo, 120 (cento e vinte) dias corridos  informações do  contados da Data de Aquisição do respectivo  Agente de  vi) Direito Creditório Elegível pelo Fundo,  Formalização e  observado que 5% (cinco por cento) dos  declaração da  Direitos Creditórios Elegíveis poderão ter  Cedente  prazo inferior a 120 (cento e vinte) dias;
 os Direitos Creditórios não poderão ser Gestora, com  devidos por Devedor (considerado em informações do  conjunto com os demais integrantes do seu Agente de  vii)  Grupo Econômico) que esteja inadimplente Formalização e  com o Fundo e com a Cedente por um declaração da  período superior a 5 (cinco) dias corridos; e Cedente  considerando-se pro forma a cessão  pretendida, a soma do Valor de Aquisição ou  Valor Presente dos Direitos Creditórios  devidos por (i) um mesmo Devedor  (considerado em conjunto com as demais  integrantes do seu Grupo Econômico, de  acordo com critérios do departamento de  Gestora, com  crédito da BASF), conforme previamente  informações do  cadastrado junto ao Custodiante, não  viii) Agente de  poderá representar concentração superior a  Formalização e da  3% (três por cento) do Patrimônio Líquido do  Administradora  Fundo; e (ii) qualquer Grande Grupo  Econômico de Devedores, não poderá  representar concentração superior à  disposta no Anexo IV do Contrato de Gestão  para o respectivo Grande Grupo Econômico  de Devedores, conforme previamente  cadastrados junto ao Custodiante.", "sha256": "2e89a71cde9ceccd2584e6089c2a4d15712f2efda1a7b8ffa04338d29a91896b", "verification": "primary_passage"}, {"document_id": "801978", "title": "Regulamento", "url": "https://fnet.bmfbovespa.com.br/fnet/publico/visualizarDocumento?id=801978", "reference_date": "2024-12-12", "version": "1", "page": 41, "clause": "", "excerpt": "Responsável pela  Item Critério de Elegibilidade  verificação  deverão ser devidos por um mesmo Devedor,  quando considerados em conjunto com os  Direitos Creditórios Adquiridos LF, não
 i) Gestora  poderão representar concentração superior  a 20% (vinte por cento) do Patrimônio  Líquido do Fundo;
 deverão ter data de vencimento anterior à  ii) última Data de Resgate Esperada das Cotas Gestora  Seniores em circulação; e  não poderão, de forma agregada,  representar montante superior a 50%  iii) Gestora  (cinquenta por cento) do Patrimônio Líquido  do Fundo.", "sha256": "2e89a71cde9ceccd2584e6089c2a4d15712f2efda1a7b8ffa04338d29a91896b", "verification": "primary_passage"}]

[{"document_id": "957854", "title": "Regulamento", "url": "https://fnet.bmfbovespa.com.br/fnet/publico/visualizarDocumento?id=957854", "reference_date": "2025-07-30", "version": "1", "page": 43, "clause": "", "excerpt": "“Alocação Mínima de Significa a alocação de, pelo menos, 67% (sessenta e sete por  Investimento” cento) do Patrimônio Líquido em Direitos Creditórios Elegíveis.", "sha256": "c110bef561ae53440e91ecc6054735219c05102c166473139d2b074c5a0c1007", "verification": "primary_passage"}, {"document_id": "957854", "title": "Regulamento", "url": "https://fnet.bmfbovespa.com.br/fnet/publico/visualizarDocumento?id=957854", "reference_date": "2025-07-30", "version": "1", "page": 66, "clause": "", "excerpt": "(vii) considerando-se pro forma a aquisição  pretendida, o valor de face dos Direitos Gestor, com base nas informações do Cedente e  Creditórios devidos por Devedores do Agente de Formalização  (considerado em conjunto com as demais  integrantes do seu Grupo Econômico) com  sede ou domicílio no Estado do Rio Grande do  Sul, devem estar limitados a 30% (trinta por  cento) do Patrimônio Líquido da Classe;
 DIREITOS CREDITÓRIOS (“PRAZO”)  Gestor, com base nas informações do Cedente e
 (viii) os Direitos Creditórios deverão ter prazo do Agente de Formalização  mínimo de vencimento de 30 (trinta) dias,  contados da Data de Aquisição;
 GRUPO ECONÔMICO (“CONCENTRAÇÃO”)", "sha256": "c110bef561ae53440e91ecc6054735219c05102c166473139d2b074c5a0c1007", "verification": "primary_passage"}]

[{"document_id": "957854", "title": "Regulamento", "url": "https://fnet.bmfbovespa.com.br/fnet/publico/visualizarDocumento?id=957854", "reference_date": "2025-07-30", "version": "1", "page": 100, "clause": "10.2", "excerpt": "10.2. Na hipótese de desenquadramento de quaisquer dos percentuais abaixo para os  Índices de Monitoramento, o Gestor deverá comunicar os Cotistas imediatamente, fornecendo as  informações necessárias acerca do percentual em questão, bem como sobre eventuais providências  a serem adotadas, conforme aplicável:
(i) Índice de Subordinação deverá corresponder a, no mínimo, 20% (vinte por cento);
(ii) Índice de Concentração Devedores, que deverá ser de até 3% (três por cento) do Patrimônio  Líquido;
(iii) Índice de Concentração Devedores Especiais, que deverá ser de até 10% (dez inteiros por  cento);", "sha256": "c110bef561ae53440e91ecc6054735219c05102c166473139d2b074c5a0c1007", "verification": "primary_passage"}]

[{"document_id": "957854", "title": "Regulamento", "url": "https://fnet.bmfbovespa.com.br/fnet/publico/visualizarDocumento?id=957854", "reference_date": "2025-07-30", "version": "1", "page": 95, "clause": "8.20", "excerpt": "8.20. A Ordem de Alocação de Recursos em datas que não sejam Datas de Pagamento  ocorrerá da seguinte forma:
(i) pagamento das despesas e encargos do Fundo;
(ii) constituição e/ou recomposição da Reserva de Despesas;
(iii) aquisição de Direitos Creditórios nos termos deste Anexo Descritivo e do Contrato de  Cessão; e
(iv) aquisição de Ativos Financeiros.", "sha256": "c110bef561ae53440e91ecc6054735219c05102c166473139d2b074c5a0c1007", "verification": "primary_passage"}, {"document_id": "957854", "title": "Regulamento", "url": "https://fnet.bmfbovespa.com.br/fnet/publico/visualizarDocumento?id=957854", "reference_date": "2025-07-30", "version": "1", "page": 95, "clause": "8.21", "excerpt": "8.21. A Ordem de Alocação de Recursos em datas que sejam Datas de Pagamento  ocorrerá da seguinte forma:
(i) pagamento das despesas e encargos do Fundo;
(ii) constituição e/ou recomposição da Reserva de Despesas;
(iii) pagamento da Meta de Amortização e Meta de Remuneração relativa às Cotas Seniores em  circulação até o Resgate;
(iv) pagamento da Meta de Amortização e Meta de Remuneração relativa às Cotas Subordinadas  Mezanino em circulação;
(v) pagamento do Prêmio de Excesso de Spread aos titulares das Cotas Subordinadas  Mezanino;
(vi) Resgate das Cotas Subordinadas Mezanino; e", "sha256": "c110bef561ae53440e91ecc6054735219c05102c166473139d2b074c5a0c1007", "verification": "primary_passage"}, {"document_id": "957854", "title": "Regulamento", "url": "https://fnet.bmfbovespa.com.br/fnet/publico/visualizarDocumento?id=957854", "reference_date": "2025-07-30", "version": "1", "page": 98, "clause": "9.1", "excerpt": "9.1. Reserva de Despesas. A partir da 1ª Data de Integralização, o Gestor estabelecerá a  Reserva de Despesas. A Reserva de Despesas será constituída quando da integralização das Cotas  e será custeada pelos recursos recebidos pela Classe. Os recursos mantidos na Reserva de Despesas  serão investidos em Ativos Financeiros. A Classe deterá todos os direitos em relação aos Ativos  Financeiros e a todos os valores em dinheiro mantidos na Reserva de Despesas, sendo que os  respectivos rendimentos reverterão em benefício dos Cotistas.", "sha256": "c110bef561ae53440e91ecc6054735219c05102c166473139d2b074c5a0c1007", "verification": "primary_passage"}]

[{"document_id": "1247697", "title": "Regulamento", "url": "https://fnet.bmfbovespa.com.br/fnet/publico/visualizarDocumento?id=1247697", "reference_date": "2026-07-09", "version": "1", "page": 71, "clause": "", "excerpt": "Critérios de Elegibilidade Validação
 (i) DIREITOS CREDITÓRIOS  (PRAZO)  Os Direitos Creditórios deverão GESTOR COM BASE NAS  ter data de vencimento de, pelo INFORMAÇÕES DO AGENTE  menos, 30 (trinta) dias anteriores DE FORMALIZAÇÃO  à última Data de Resgate das  Cotas Seniores em circulação;
 (ii) DIREITOS CREDITÓRIOS  (PRAZO)  Os Direitos Creditórios deverão GESTOR COM BASE NAS  ter prazo máximo de vencimento INFORMAÇÕES DO AGENTE  de até 365 (trezentos e sessenta e DE FORMALIZAÇÃO  cinco) dias com base na Data de  Aquisição;
 (iii) DIREITOS CREDITÓRIOS  (PRAZO MÍNIMO) GESTOR COM BASE NAS  Os Direitos Creditórios deverão INFORMAÇÕES DO AGENTE  ter prazo mínimo de vencimento DE FORMALIZAÇÃO  de 10 (dez) dias;
 (iv) DEVEDORES  (CONCENTRAÇÃO)  Considerando-se pro forma a  aquisição pretendida, o valor de GESTOR COM BASE NAS  face dos Direitos Creditórios INFORMAÇÕES DO AGENTE  devidos de um mesmo Devedor DE FORMALIZAÇÃO,  (considerado em conjunto com as CUSTODIANTE e CEDENTE  demais integrantes do seu Grupo  Econômico), devem estar  limitados a 3% (três por cento) do  Patrimônio Líquido da Classe;", "sha256": "1aa6d0b434ad45d715649605bdeafefea51e8eca0f2d6d4cf69eadee214c7ac4", "verification": "primary_passage"}]

[{"document_id": "1247697", "title": "Regulamento", "url": "https://fnet.bmfbovespa.com.br/fnet/publico/visualizarDocumento?id=1247697", "reference_date": "2026-07-09", "version": "1", "page": 48, "clause": "", "excerpt": "“Alocação Mínima de Significa a alocação de, pelo menos, 67% (sessenta e sete por  Investimento” cento) do Patrimônio Líquido em Direitos Creditórios Elegíveis.", "sha256": "1aa6d0b434ad45d715649605bdeafefea51e8eca0f2d6d4cf69eadee214c7ac4", "verification": "primary_passage"}, {"document_id": "1247697", "title": "Regulamento", "url": "https://fnet.bmfbovespa.com.br/fnet/publico/visualizarDocumento?id=1247697", "reference_date": "2026-07-09", "version": "1", "page": 71, "clause": "", "excerpt": "Critérios de Elegibilidade Validação
 (i) DIREITOS CREDITÓRIOS  (PRAZO)  Os Direitos Creditórios deverão GESTOR COM BASE NAS  ter data de vencimento de, pelo INFORMAÇÕES DO AGENTE  menos, 30 (trinta) dias anteriores DE FORMALIZAÇÃO  à última Data de Resgate das  Cotas Seniores em circulação;
 (ii) DIREITOS CREDITÓRIOS  (PRAZO)  Os Direitos Creditórios deverão GESTOR COM BASE NAS  ter prazo máximo de vencimento INFORMAÇÕES DO AGENTE  de até 365 (trezentos e sessenta e DE FORMALIZAÇÃO  cinco) dias com base na Data de  Aquisição;
 (iii) DIREITOS CREDITÓRIOS  (PRAZO MÍNIMO) GESTOR COM BASE NAS  Os Direitos Creditórios deverão INFORMAÇÕES DO AGENTE  ter prazo mínimo de vencimento DE FORMALIZAÇÃO  de 10 (dez) dias;
 (iv) DEVEDORES  (CONCENTRAÇÃO)  Considerando-se pro forma a  aquisição pretendida, o valor de GESTOR COM BASE NAS  face dos Direitos Creditórios INFORMAÇÕES DO AGENTE  devidos de um mesmo Devedor DE FORMALIZAÇÃO,  (considerado em conjunto com as CUSTODIANTE e CEDENTE  demais integrantes do seu Grupo  Econômico), devem estar  limitados a 3% (três por cento) do  Patrimônio Líquido da Classe;", "sha256": "1aa6d0b434ad45d715649605bdeafefea51e8eca0f2d6d4cf69eadee214c7ac4", "verification": "primary_passage"}]

[{"document_id": "1247697", "title": "Regulamento", "url": "https://fnet.bmfbovespa.com.br/fnet/publico/visualizarDocumento?id=1247697", "reference_date": "2026-07-09", "version": "1", "page": 105, "clause": "10.1", "excerpt": "10.1. Índices de Monitoramento. O Gestor verificará nas Datas de Verificação os  seguintes Índices de Monitoramento de desempenho da Classe:
(i) “Índice de Subordinação Sênior” ou “Índice de Subordinação” significa a razão entre  o valor total das Cotas Seniores e o Patrimônio Líquido, que deverá ser apurada pelo  Gestor e deverá corresponder a, no máximo, 80% (oitenta por cento);
(ii) “Índice de Concentração Devedores” significa, para cada mês, o índice, em cada Data  de Verificação, que apura a concentração dos Devedores, que deve ser de até 3% (três  por cento) do Patrimônio Médio Líquido do Fundo, considerando os Devedores por  Grupo Econômico;
(iii) Índice de Concentração Cedentes” significa, para cada mês, o percentual equivalente  a uma fração cujo numerador é igual à soma dos valores presentes (valor do  administrador) dos Direitos Creditórios Cedidos por cada Cedente e o denominador  é igual ao Patrimônio Médio Líquido do Fundo;
(iv) “Índice de Recompra e de Alienação por Portabilidade” significa, para cada mês, o  percentual equivalente a uma fração cujo numerador é igual à soma dos valores", "sha256": "1aa6d0b434ad45d715649605bdeafefea51e8eca0f2d6d4cf69eadee214c7ac4", "verification": "primary_passage"}, {"document_id": "1247697", "title": "Regulamento", "url": "https://fnet.bmfbovespa.com.br/fnet/publico/visualizarDocumento?id=1247697", "reference_date": "2026-07-09", "version": "1", "page": 111, "clause": "", "excerpt": "(xx) observado o prazo de cura de 15 (quinze) dias contados da respectiva Data de  Verificação, em qualquer mês, com base no último Dia Útil de cada mês, a partir da  primeira integralização de Cotas Seniores (inclusive), o Índice de Subordinação  Sênior for menor que 20%.", "sha256": "1aa6d0b434ad45d715649605bdeafefea51e8eca0f2d6d4cf69eadee214c7ac4", "verification": "primary_passage"}]

[{"document_id": "1247697", "title": "Regulamento", "url": "https://fnet.bmfbovespa.com.br/fnet/publico/visualizarDocumento?id=1247697", "reference_date": "2026-07-09", "version": "1", "page": 100, "clause": "8.19", "excerpt": "8.19. A Ordem de Alocação de Recursos em datas que não sejam Datas de  Pagamento, caso a Amortização Pro Rata esteja em curso, ocorrerá da seguinte forma:
(i) pagamento das despesas e encargos do Fundo;
(ii) pagamentos de despesas e encargos relativos às operações com Derivativos;
(iii) constituição e/ou recomposição da Reserva de Liquidez;
(iv) aquisição de Direitos Creditórios nos termos deste Anexo Descritivo e do Contrato  de Cessão; e
(v) aquisição de Ativos Financeiros.", "sha256": "1aa6d0b434ad45d715649605bdeafefea51e8eca0f2d6d4cf69eadee214c7ac4", "verification": "primary_passage"}, {"document_id": "1247697", "title": "Regulamento", "url": "https://fnet.bmfbovespa.com.br/fnet/publico/visualizarDocumento?id=1247697", "reference_date": "2026-07-09", "version": "1", "page": 100, "clause": "8.20", "excerpt": "8.20. A Ordem de Alocação de Recursos em datas que não sejam Datas de  Pagamento, caso a Amortização Sequencial esteja em curso, ocorrerá da seguinte forma:
(i) pagamento das despesas e encargos do Fundo;
(ii) pagamentos de despesas e encargos relativos às operações com Derivativos;
(iii) constituição e/ou recomposição da Reserva de Liquidez;
(iv) e aquisição de Ativos Financeiros.", "sha256": "1aa6d0b434ad45d715649605bdeafefea51e8eca0f2d6d4cf69eadee214c7ac4", "verification": "primary_passage"}, {"document_id": "1247697", "title": "Regulamento", "url": "https://fnet.bmfbovespa.com.br/fnet/publico/visualizarDocumento?id=1247697", "reference_date": "2026-07-09", "version": "1", "page": 104, "clause": "9.1", "excerpt": "9.1. Reserva de Liquidez. A partir da 1ª Data de Integralização, o Gestor  estabelecerá a Reserva de Liquidez. A Reserva de Liquidez será constituída quando da  integralização das Cotas e será custeada pelos recursos recebidos pela Classe. Os recursos  mantidos na Reserva de Liquidez serão investidos em Ativos Financeiros. A Classe deterá  todos os direitos em relação aos Ativos Financeiros e a todos os valores em dinheiro mantidos  na Reserva de Liquidez, sendo que os respectivos rendimentos reverterão em benefício dos  Cotistas.", "sha256": "1aa6d0b434ad45d715649605bdeafefea51e8eca0f2d6d4cf69eadee214c7ac4", "verification": "primary_passage"}]

