[{"document_id": "1152539", "title": "Regulamento", "url": "https://fnet.bmfbovespa.com.br/fnet/publico/visualizarDocumento?id=1152539", "reference_date": "2026-03-31", "version": "1", "page": 69, "clause": "11.4.1", "excerpt": "11.4.1. O Fundo somente poderá adquirir Direitos Creditórios que atendam cumulativamente aos seguintes Critérios de Elegibilidade:
(i) os Direitos Creditórios devem ser expressos em moeda corrente nacional;
(ii) o prazo entre a Data de Aquisição e a data de vencimento de cada Direito Creditório a  ser adquirido deverá ser de, no máximo, 360 (trezentos e sessenta) dias corridos;
(iii) os Direitos Creditórios deverão ser provenientes do pagamento devido pelos  Devedores ao Cedente, decorrente das Transações de Pagamento realizadas por  Usuários-Finais utilizando-se de Instrumentos de Pagamento das Bandeiras, na  modalidade “crédito”, operacionalizados pelo Sistema SumUp para a aquisição de bens  e serviços ofertados pelos Estabelecimentos Comerciais;
(iv) os Direitos Creditórios devem ser devidos pelos Devedores, não havendo limites de  concentração estabelecidos por Devedor; e
(v) o Cedente não poderá estar inadimplente perante o Fundo.", "sha256": "b135d763db0af3d762d18af161ce054a51d7f696dca7cd3c16dbc9c50a963d08", "verification": "primary_passage"}]

